window.CIYU_SPLIT_SEED_DATA = {"10.1": [{"id": "10-0", "hanzi": "干净", "pinyin": "gānjìng", "meaning": "clean", "example_cn": "我住的地方真干净。", "example_en": "The place where I live is really clean.", "lesson": 10.1}, {"id": "10-1", "hanzi": "破坏", "pinyin": "pòhuài", "meaning": "to damage; to destroy", "example_cn": "四处乱画会破坏环境。", "example_en": "Drawing everywhere damages the environment.", "lesson": 10.1}, {"id": "10-2", "hanzi": "环境", "pinyin": "huánjìng", "meaning": "environment", "example_cn": "我住的地方环境很好。", "example_en": "The environment where I live is very nice.", "lesson": 10.1}, {"id": "10-3", "hanzi": "四处", "pinyin": "sìchù", "meaning": "everywhere", "example_cn": "小狗在公园里四处跑。", "example_en": "The puppy runs everywhere in the park.", "lesson": 10.1}, {"id": "10-4", "hanzi": "涂鸦", "pinyin": "túyā", "meaning": "to scribble; graffiti", "example_cn": "不可以在墙上涂鸦。", "example_en": "You must not scribble on the wall.", "lesson": 10.1}, {"id": "10-5", "hanzi": "引来", "pinyin": "yǐnlái", "meaning": "to attract; to draw", "example_cn": "乱扔垃圾会引来蚊虫。", "example_en": "Littering will attract mosquitoes and insects.", "lesson": 10.1}, {"id": "10-6", "hanzi": "蚊虫", "pinyin": "wénchóng", "meaning": "mosquitoes and insects", "example_cn": "夏天的晚上蚊虫很多。", "example_en": "There are many mosquitoes and insects on summer nights.", "lesson": 10.1}, {"id": "10-7", "hanzi": "随地", "pinyin": "suídì", "meaning": "anywhere; wherever one likes", "example_cn": "不可以随地吐痰。", "example_en": "You must not spit anywhere you like.", "lesson": 10.1}, {"id": "10-8", "hanzi": "小便", "pinyin": "xiǎobiàn", "meaning": "to urinate; to pee", "example_cn": "随地小便是不对的。", "example_en": "Peeing anywhere is wrong.", "lesson": 10.1}, {"id": "10-9", "hanzi": "蚊子", "pinyin": "wénzi", "meaning": "mosquito", "example_cn": "我的手被蚊子咬了。", "example_en": "My hand was bitten by a mosquito.", "lesson": 10.1}, {"id": "10-10", "hanzi": "苍蝇", "pinyin": "cāngying", "meaning": "fly (insect)", "example_cn": "一只苍蝇飞进了厨房。", "example_en": "A fly flew into the kitchen.", "lesson": 10.1}, {"id": "10-11", "hanzi": "蟑螂", "pinyin": "zhāngláng", "meaning": "cockroach", "example_cn": "厨房里有一只蟑螂。", "example_en": "There is a cockroach in the kitchen.", "lesson": 10.1}, {"id": "10-12", "hanzi": "乱扔", "pinyin": "luàn rēng", "meaning": "to throw carelessly; to litter", "example_cn": "请不要乱扔垃圾。", "example_en": "Please do not litter.", "lesson": 10.1}, {"id": "10-13", "hanzi": "垃圾", "pinyin": "lājī", "meaning": "rubbish; trash", "example_cn": "地上有很多垃圾。", "example_en": "There is a lot of rubbish on the ground.", "lesson": 10.1}, {"id": "10-14", "hanzi": "觉得", "pinyin": "juéde", "meaning": "to think; to feel", "example_cn": "我觉得摘花是不对的。", "example_en": "I think picking flowers is wrong.", "lesson": 10.1}, {"id": "10-15", "hanzi": "因为", "pinyin": "yīnwèi", "meaning": "because", "example_cn": "我今天没上学，因为我生病了。", "example_en": "I didn't go to school today because I was sick.", "lesson": 10.1}, {"id": "10-16", "hanzi": "应该", "pinyin": "yīnggāi", "meaning": "should; ought to", "example_cn": "你应该早点儿睡觉。", "example_en": "You should go to bed earlier.", "lesson": 10.1}, {"id": "10-17", "hanzi": "保护", "pinyin": "bǎohù", "meaning": "to protect", "example_cn": "我们应该保护环境。", "example_en": "We should protect the environment.", "lesson": 10.1}, {"id": "10-18", "hanzi": "保持", "pinyin": "bǎochí", "meaning": "to keep; to maintain", "example_cn": "我们要保持课室干净。", "example_en": "We must keep the classroom clean.", "lesson": 10.1}, {"id": "10-19", "hanzi": "卫生", "pinyin": "wèishēng", "meaning": "hygiene; cleanliness", "example_cn": "大家要注意个人卫生。", "example_en": "Everyone should pay attention to personal hygiene.", "lesson": 10.1}, {"id": "10-20", "hanzi": "爱护", "pinyin": "àihù", "meaning": "to cherish; to take good care of", "example_cn": "我们要爱护课本。", "example_en": "We should take good care of our textbooks.", "lesson": 10.1}], "10.2": [{"id": "10-21", "hanzi": "看法", "pinyin": "kànfǎ", "meaning": "opinion; view", "example_cn": "请说出你的看法。", "example_en": "Please share your opinion.", "lesson": 10.2}, {"id": "10-22", "hanzi": "原因", "pinyin": "yuányīn", "meaning": "reason; cause", "example_cn": "请说明你迟到的原因。", "example_en": "Please explain the reason you were late.", "lesson": 10.2}, {"id": "10-23", "hanzi": "建议", "pinyin": "jiànyì", "meaning": "suggestion; to suggest", "example_cn": "老师给了我一个好建议。", "example_en": "The teacher gave me a good suggestion.", "lesson": 10.2}, {"id": "10-24", "hanzi": "摘", "pinyin": "zhāi", "meaning": "to pick (flowers, fruit)", "example_cn": "我们不应该摘公园里的花。", "example_en": "We should not pick the flowers in the park.", "lesson": 10.2}, {"id": "10-25", "hanzi": "花草", "pinyin": "huācǎo", "meaning": "flowers and plants", "example_cn": "我们应该爱护花草。", "example_en": "We should take care of flowers and plants.", "lesson": 10.2}, {"id": "10-26", "hanzi": "又脏又乱", "pinyin": "yòu zāng yòu luàn", "meaning": "dirty and messy", "example_cn": "我的房间又脏又乱。", "example_en": "My room is dirty and messy.", "lesson": 10.2}, {"id": "10-27", "hanzi": "收拾", "pinyin": "shōushi", "meaning": "to tidy up", "example_cn": "我们来收拾一下房间吧。", "example_en": "Let's tidy up the room.", "lesson": 10.2}, {"id": "10-28", "hanzi": "厕所", "pinyin": "cèsuǒ", "meaning": "toilet", "example_cn": "学校的厕所很干净。", "example_en": "The school toilets are very clean.", "lesson": 10.2}, {"id": "10-29", "hanzi": "臭", "pinyin": "chòu", "meaning": "smelly", "example_cn": "垃圾桶很臭。", "example_en": "The rubbish bin is very smelly.", "lesson": 10.2}, {"id": "10-30", "hanzi": "清洗", "pinyin": "qīngxǐ", "meaning": "to wash; to clean", "example_cn": "妈妈在厨房清洗碗碟。", "example_en": "Mum is washing the dishes in the kitchen.", "lesson": 10.2}], "10.3": [{"id": "10-31", "hanzi": "周末", "pinyin": "zhōumò", "meaning": "weekend", "example_cn": "周末我去上美术课。", "example_en": "I go to art class on weekends.", "lesson": 10.3}, {"id": "10-32", "hanzi": "美术课", "pinyin": "měishù kè", "meaning": "art class", "example_cn": "我最喜欢上美术课。", "example_en": "I like art class the most.", "lesson": 10.3}, {"id": "10-33", "hanzi": "仔细", "pinyin": "zǐxì", "meaning": "carefully", "example_cn": "请仔细地看这些花。", "example_en": "Please look at these flowers carefully.", "lesson": 10.3}, {"id": "10-34", "hanzi": "胡姬花", "pinyin": "hújīhuā", "meaning": "orchid", "example_cn": "胡姬花是新加坡的国花。", "example_en": "The orchid is Singapore's national flower.", "lesson": 10.3}, {"id": "10-35", "hanzi": "摇摆", "pinyin": "yáobǎi", "meaning": "to sway", "example_cn": "小草在风中轻轻地摇摆。", "example_en": "The grass sways gently in the wind.", "lesson": 10.3}, {"id": "10-36", "hanzi": "打招呼", "pinyin": "dǎ zhāohu", "meaning": "to greet; to say hello", "example_cn": "我向老师打招呼。", "example_en": "I say hello to the teacher.", "lesson": 10.3}, {"id": "10-37", "hanzi": "决定", "pinyin": "juédìng", "meaning": "to decide", "example_cn": "我决定画这枝花。", "example_en": "I decided to draw this flower.", "lesson": 10.3}, {"id": "10-38", "hanzi": "吃惊", "pinyin": "chījīng", "meaning": "surprised; shocked", "example_cn": "美美听了很吃惊。", "example_en": "Meimei was very surprised when she heard it.", "lesson": 10.3}, {"id": "10-39", "hanzi": "转身", "pinyin": "zhuǎnshēn", "meaning": "to turn around", "example_cn": "他转身就走了。", "example_en": "He turned around and left.", "lesson": 10.3}, {"id": "10-40", "hanzi": "离开", "pinyin": "líkāi", "meaning": "to leave", "example_cn": "美美说完就离开了。", "example_en": "Meimei left after she finished speaking.", "lesson": 10.3}, {"id": "10-41", "hanzi": "伸出", "pinyin": "shēnchū", "meaning": "to stretch out; to reach out", "example_cn": "我伸出手去拿书。", "example_en": "I reached out my hand to get the book.", "lesson": 10.3}, {"id": "10-42", "hanzi": "缩", "pinyin": "suō", "meaning": "to pull back; to shrink", "example_cn": "他又把手缩了回来。", "example_en": "He pulled his hand back again.", "lesson": 10.3}, {"id": "10-43", "hanzi": "追上", "pinyin": "zhuīshàng", "meaning": "to catch up with", "example_cn": "我快步地追上美美。", "example_en": "I walked quickly to catch up with Meimei.", "lesson": 10.3}], "10.4": [{"id": "10-44", "hanzi": "谜语", "pinyin": "míyǔ", "meaning": "riddle", "example_cn": "你能猜出这个谜语吗？", "example_en": "Can you guess this riddle?", "lesson": 10.4}, {"id": "10-45", "hanzi": "灰尘", "pinyin": "huīchén", "meaning": "dust", "example_cn": "桌上有很多灰尘。", "example_en": "There is a lot of dust on the table.", "lesson": 10.4}, {"id": "10-46", "hanzi": "肮脏", "pinyin": "āngzāng", "meaning": "filthy; dirty", "example_cn": "这条小河很肮脏。", "example_en": "This little river is very filthy.", "lesson": 10.4}, {"id": "10-47", "hanzi": "剪刀", "pinyin": "jiǎndāo", "meaning": "scissors", "example_cn": "我向他借剪刀。", "example_en": "I borrow scissors from him.", "lesson": 10.4}, {"id": "10-48", "hanzi": "剪纸", "pinyin": "jiǎnzhǐ", "meaning": "paper-cutting", "example_cn": "我向表哥学剪纸。", "example_en": "I learn paper-cutting from my cousin.", "lesson": 10.4}], "10.5": [{"id": "10-49", "hanzi": "墙壁", "pinyin": "qiángbì", "meaning": "wall", "example_cn": "墙壁上有一幅画。", "example_en": "There is a picture on the wall.", "lesson": 10.5}, {"id": "10-50", "hanzi": "组屋", "pinyin": "zǔwū", "meaning": "HDB flat (public housing)", "example_cn": "我家住在组屋里。", "example_en": "My family lives in an HDB flat.", "lesson": 10.5}, {"id": "10-51", "hanzi": "休息", "pinyin": "xiūxi", "meaning": "to rest", "example_cn": "打完球，他在树下休息。", "example_en": "After playing ball, he rested under the tree.", "lesson": 10.5}, {"id": "10-52", "hanzi": "少年", "pinyin": "shàonián", "meaning": "teenager; youth", "example_cn": "两个少年在打篮球。", "example_en": "Two teenagers are playing basketball.", "lesson": 10.5}, {"id": "10-53", "hanzi": "阻止", "pinyin": "zǔzhǐ", "meaning": "to stop; to prevent", "example_cn": "康康走过去阻止他们。", "example_en": "Kangkang walked over to stop them.", "lesson": 10.5}, {"id": "10-54", "hanzi": "理睬", "pinyin": "lǐcǎi", "meaning": "to pay attention to", "example_cn": "他生气了，不理睬我。", "example_en": "He got angry and ignored me.", "lesson": 10.5}, {"id": "10-55", "hanzi": "继续", "pinyin": "jìxù", "meaning": "to continue", "example_cn": "休息一下，我们再继续做功课。", "example_en": "Let's rest a bit, then continue doing homework.", "lesson": 10.5}, {"id": "10-56", "hanzi": "管闲事", "pinyin": "guǎn xiánshì", "meaning": "to mind other people's business; to meddle", "example_cn": "他很喜欢管闲事。", "example_en": "He likes to meddle in other people's business.", "lesson": 10.5}, {"id": "10-57", "hanzi": "不以为然", "pinyin": "bù yǐ wéi rán", "meaning": "to not take seriously; dismissive", "example_cn": "他听了，不以为然地笑了笑。", "example_en": "He heard it and smiled dismissively.", "lesson": 10.5}, {"id": "10-58", "hanzi": "清楚", "pinyin": "qīngchu", "meaning": "clear; clearly", "example_cn": "黑板上的字我看得很清楚。", "example_en": "I can see the words on the board very clearly.", "lesson": 10.5}, {"id": "10-59", "hanzi": "擦", "pinyin": "cā", "meaning": "to wipe", "example_cn": "请把桌子擦干净。", "example_en": "Please wipe the table clean.", "lesson": 10.5}, {"id": "10-60", "hanzi": "邻居", "pinyin": "línjū", "meaning": "neighbour", "example_cn": "林爷爷是我的邻居。", "example_en": "Grandpa Lin is my neighbour.", "lesson": 10.5}, {"id": "10-61", "hanzi": "不好意思", "pinyin": "bù hǎo yìsi", "meaning": "embarrassed; shy", "example_cn": "他做错了事，有点儿不好意思。", "example_en": "He did something wrong and felt a bit embarrassed.", "lesson": 10.5}, {"id": "10-62", "hanzi": "赶紧", "pinyin": "gǎnjǐn", "meaning": "hurriedly; quickly", "example_cn": "下雨了，我们赶紧回家。", "example_en": "It's raining, let's hurry home.", "lesson": 10.5}, {"id": "10-63", "hanzi": "清洁剂", "pinyin": "qīngjiéjì", "meaning": "detergent; cleaning liquid", "example_cn": "妈妈用清洁剂洗厕所。", "example_en": "Mum uses detergent to clean the toilet.", "lesson": 10.5}, {"id": "10-64", "hanzi": "抹布", "pinyin": "mābù", "meaning": "cleaning cloth; rag", "example_cn": "我用抹布擦桌子。", "example_en": "I wipe the table with a cloth.", "lesson": 10.5}, {"id": "10-65", "hanzi": "满意", "pinyin": "mǎnyì", "meaning": "satisfied; pleased", "example_cn": "老师看了我的画，满意地笑了。", "example_en": "The teacher looked at my drawing and smiled with satisfaction.", "lesson": 10.5}], "11.1": [{"id": "11-0", "hanzi": "环保", "pinyin": "huánbǎo", "meaning": "environmental protection", "example_cn": "“环保”就是“环境保护”。", "example_en": "\"Huanbao\" means \"environmental protection\".", "lesson": 11.1}, {"id": "11-1", "hanzi": "小天使", "pinyin": "xiǎo tiānshǐ", "meaning": "little angel", "example_cn": "如果你是环保小天使，你会怎么做？", "example_en": "If you were a little environmental angel, what would you do?", "lesson": 11.1}, {"id": "11-2", "hanzi": "如果", "pinyin": "rúguǒ", "meaning": "if", "example_cn": "如果大家都用环保袋，就能保护环境。", "example_en": "If everyone uses reusable bags, we can protect the environment.", "lesson": 11.1}, {"id": "11-3", "hanzi": "垃圾分类", "pinyin": "lājī fēnlèi", "meaning": "sorting rubbish", "example_cn": "我们在家里做垃圾分类。", "example_en": "We sort our rubbish at home.", "lesson": 11.1}, {"id": "11-4", "hanzi": "回收箱", "pinyin": "huíshōuxiāng", "meaning": "recycling bin", "example_cn": "用过的瓶子，我们可以放进回收箱里。", "example_en": "We can put used bottles into the recycling bin.", "lesson": 11.1}, {"id": "11-5", "hanzi": "玻璃罐", "pinyin": "bōliguàn", "meaning": "glass jar", "example_cn": "妈妈用玻璃罐装糖果。", "example_en": "Mum uses a glass jar to hold sweets.", "lesson": 11.1}, {"id": "11-6", "hanzi": "纸盒", "pinyin": "zhǐhé", "meaning": "paper box; carton", "example_cn": "没用的纸盒可以拿去回收。", "example_en": "Unwanted paper boxes can be recycled.", "lesson": 11.1}, {"id": "11-7", "hanzi": "塑料袋", "pinyin": "sùliàodài", "meaning": "plastic bag", "example_cn": "我们要少用塑料袋。", "example_en": "We should use fewer plastic bags.", "lesson": 11.1}, {"id": "11-8", "hanzi": "塑料瓶", "pinyin": "sùliàopíng", "meaning": "plastic bottle", "example_cn": "喝完的塑料瓶不要乱扔。", "example_en": "Don't throw empty plastic bottles around.", "lesson": 11.1}, {"id": "11-9", "hanzi": "金属罐", "pinyin": "jīnshǔguàn", "meaning": "metal can", "example_cn": "金属罐要放进黄色的回收箱。", "example_en": "Metal cans go into the yellow recycling bin.", "lesson": 11.1}, {"id": "11-10", "hanzi": "认为", "pinyin": "rènwéi", "meaning": "to think; to believe", "example_cn": "我认为使用环保袋是对的。", "example_en": "I think using reusable bags is right.", "lesson": 11.1}, {"id": "11-11", "hanzi": "使用", "pinyin": "shǐyòng", "meaning": "to use", "example_cn": "我们应该使用环保袋。", "example_en": "We should use reusable bags.", "lesson": 11.1}, {"id": "11-12", "hanzi": "环保袋", "pinyin": "huánbǎodài", "meaning": "reusable shopping bag", "example_cn": "妈妈去买东西时总是带着环保袋。", "example_en": "Mum always brings a reusable bag when she goes shopping.", "lesson": 11.1}, {"id": "11-13", "hanzi": "浪费", "pinyin": "làngfèi", "meaning": "to waste", "example_cn": "开着灯睡觉会浪费电。", "example_en": "Sleeping with the light on wastes electricity.", "lesson": 11.1}, {"id": "11-14", "hanzi": "报纸", "pinyin": "bàozhǐ", "meaning": "newspaper", "example_cn": "爸爸每天早上都看报纸。", "example_en": "Dad reads the newspaper every morning.", "lesson": 11.1}, {"id": "11-15", "hanzi": "废物利用", "pinyin": "fèiwù lìyòng", "meaning": "to reuse waste materials", "example_cn": "读过的报纸，我们可以废物利用。", "example_en": "We can reuse newspapers that we have read.", "lesson": 11.1}, {"id": "11-16", "hanzi": "放进", "pinyin": "fàngjìn", "meaning": "to put into", "example_cn": "请把书放进书包里。", "example_en": "Please put the book into your school bag.", "lesson": 11.1}, {"id": "11-17", "hanzi": "瓶子", "pinyin": "píngzi", "meaning": "bottle", "example_cn": "这个瓶子里装满了水。", "example_en": "This bottle is full of water.", "lesson": 11.1}], "11.3": [{"id": "11-18", "hanzi": "记事本", "pinyin": "jìshìběn", "meaning": "notebook", "example_cn": "康康有一本绿色记事本。", "example_en": "Kangkang has a green notebook.", "lesson": 11.3}, {"id": "11-19", "hanzi": "不知不觉", "pinyin": "bù zhī bù jué", "meaning": "without realising", "example_cn": "我看书时不知不觉睡着了。", "example_en": "I fell asleep without realising while reading.", "lesson": 11.3}, {"id": "11-20", "hanzi": "睡着", "pinyin": "shuìzháo", "meaning": "to fall asleep", "example_cn": "弟弟一躺下就睡着了。", "example_en": "My little brother fell asleep as soon as he lay down.", "lesson": 11.3}, {"id": "11-21", "hanzi": "星期", "pinyin": "xīngqī", "meaning": "week; day of the week", "example_cn": "今天是星期二。", "example_en": "Today is Tuesday.", "lesson": 11.3}, {"id": "11-22", "hanzi": "关灯", "pinyin": "guān dēng", "meaning": "to turn off the light", "example_cn": "睡觉前一定要记得关灯。", "example_en": "Remember to turn off the light before going to bed.", "lesson": 11.3}, {"id": "11-23", "hanzi": "记得", "pinyin": "jìde", "meaning": "to remember", "example_cn": "你记得带作业了吗？", "example_en": "Did you remember to bring your homework?", "lesson": 11.3}, {"id": "11-24", "hanzi": "垃圾桶", "pinyin": "lājītǒng", "meaning": "rubbish bin", "example_cn": "他把画扔进了垃圾桶。", "example_en": "He threw the drawing into the rubbish bin.", "lesson": 11.3}, {"id": "11-25", "hanzi": "折成", "pinyin": "zhéchéng", "meaning": "to fold into", "example_cn": "用过的纸可以折成小纸盒。", "example_en": "Used paper can be folded into a small box.", "lesson": 11.3}, {"id": "11-26", "hanzi": "废纸", "pinyin": "fèizhǐ", "meaning": "waste paper", "example_cn": "原来废纸还能这么用啊！", "example_en": "So waste paper can be used like this!", "lesson": 11.3}, {"id": "11-27", "hanzi": "装", "pinyin": "zhuāng", "meaning": "to hold; to put in", "example_cn": "小纸盒可以用来装垃圾。", "example_en": "A small paper box can be used to hold rubbish.", "lesson": 11.3}, {"id": "11-28", "hanzi": "超市", "pinyin": "chāoshì", "meaning": "supermarket", "example_cn": "我和妈妈一起去超市。", "example_en": "Mum and I go to the supermarket together.", "lesson": 11.3}, {"id": "11-29", "hanzi": "日用品", "pinyin": "rìyòngpǐn", "meaning": "daily necessities", "example_cn": "妈妈在超市买日用品。", "example_en": "Mum buys daily necessities at the supermarket.", "lesson": 11.3}, {"id": "11-30", "hanzi": "付钱", "pinyin": "fù qián", "meaning": "to pay", "example_cn": "付钱后，我们就回家了。", "example_en": "After paying, we went home.", "lesson": 11.3}, {"id": "11-31", "hanzi": "购物", "pinyin": "gòuwù", "meaning": "to go shopping", "example_cn": "购物时要带环保袋。", "example_en": "Bring a reusable bag when you go shopping.", "lesson": 11.3}], "11.4": [{"id": "11-32", "hanzi": "清理", "pinyin": "qīnglǐ", "meaning": "to clean up", "example_cn": "政府开始清理新加坡河。", "example_en": "The government started cleaning up the Singapore River.", "lesson": 11.4}, {"id": "11-33", "hanzi": "发展", "pinyin": "fāzhǎn", "meaning": "development", "example_cn": "新加坡河与新加坡的发展有着密切的关系。", "example_en": "The Singapore River is closely linked to Singapore's development.", "lesson": 11.4}, {"id": "11-34", "hanzi": "曾经", "pinyin": "céngjīng", "meaning": "once; at one time", "example_cn": "这条河曾经很脏。", "example_en": "This river was once very dirty.", "lesson": 11.4}, {"id": "11-35", "hanzi": "臭味", "pinyin": "chòuwèi", "meaning": "bad smell", "example_cn": "河水发出阵阵的臭味。", "example_en": "The river water gave off waves of bad smells.", "lesson": 11.4}, {"id": "11-36", "hanzi": "政府", "pinyin": "zhèngfǔ", "meaning": "government", "example_cn": "政府开始了清理新加坡河的运动。", "example_en": "The government started a campaign to clean up the Singapore River.", "lesson": 11.4}, {"id": "11-37", "hanzi": "休闲", "pinyin": "xiūxián", "meaning": "leisure", "example_cn": "河的两岸成了人们休闲的好地方。", "example_en": "Both banks of the river became a great place for people to relax.", "lesson": 11.4}, {"id": "11-38", "hanzi": "尽一份力", "pinyin": "jìn yí fèn lì", "meaning": "to do one's part", "example_cn": "大家都要为环保尽一份力。", "example_en": "Everyone should do their part for the environment.", "lesson": 11.4}, {"id": "11-39", "hanzi": "超级市场", "pinyin": "chāojí shìchǎng", "meaning": "supermarket (full form)", "example_cn": "“超市”就是“超级市场”。", "example_en": "\"Chaoshi\" is short for \"chaoji shichang\" (supermarket).", "lesson": 11.4}], "11.5": [{"id": "11-40", "hanzi": "地球", "pinyin": "dìqiú", "meaning": "the Earth", "example_cn": "地球妈妈为什么哭？", "example_en": "Why is Mother Earth crying?", "lesson": 11.5}, {"id": "11-41", "hanzi": "忙碌", "pinyin": "mánglù", "meaning": "busy", "example_cn": "妈妈每天都很忙碌。", "example_en": "Mum is very busy every day.", "lesson": 11.5}, {"id": "11-42", "hanzi": "美味", "pinyin": "měiwèi", "meaning": "delicious", "example_cn": "妈妈给我们煮了美味的食物。", "example_en": "Mum cooked delicious food for us.", "lesson": 11.5}, {"id": "11-43", "hanzi": "财富", "pinyin": "cáifù", "meaning": "wealth", "example_cn": "她不能给孩子足够的财富。", "example_en": "She cannot give her children enough wealth.", "lesson": 11.5}, {"id": "11-44", "hanzi": "自私", "pinyin": "zìsī", "meaning": "selfish", "example_cn": "只想着自己的人很自私。", "example_en": "People who only think of themselves are selfish.", "lesson": 11.5}, {"id": "11-45", "hanzi": "满足", "pinyin": "mǎnzú", "meaning": "satisfied; content", "example_cn": "因为孩子总是不满足。", "example_en": "Because the children are never satisfied.", "lesson": 11.5}, {"id": "11-46", "hanzi": "建造", "pinyin": "jiànzào", "meaning": "to build", "example_cn": "人们在这里建造了一座大桥。", "example_en": "People built a big bridge here.", "lesson": 11.5}, {"id": "11-47", "hanzi": "工厂", "pinyin": "gōngchǎng", "meaning": "factory", "example_cn": "这家工厂每天排放废气。", "example_en": "This factory releases exhaust fumes every day.", "lesson": 11.5}, {"id": "11-48", "hanzi": "废气", "pinyin": "fèiqì", "meaning": "exhaust fumes; waste gas", "example_cn": "汽车排放的废气会污染空气。", "example_en": "Exhaust fumes from cars pollute the air.", "lesson": 11.5}, {"id": "11-49", "hanzi": "烟雾", "pinyin": "yānwù", "meaning": "smoke; haze", "example_cn": "火烧森林引发烟雾。", "example_en": "Burning forests causes haze.", "lesson": 11.5}, {"id": "11-50", "hanzi": "辛苦", "pinyin": "xīnkǔ", "meaning": "hard; tiring", "example_cn": "养育孩子很辛苦。", "example_en": "Raising children is hard work.", "lesson": 11.5}], "12.1": [{"id": "12-0", "hanzi": "国庆日", "pinyin": "Guóqìng Rì", "meaning": "National Day", "example_cn": "八月九日是新加坡的国庆日。", "example_en": "9 August is Singapore's National Day.", "lesson": 12.1}, {"id": "12-1", "hanzi": "庆祝", "pinyin": "qìngzhù", "meaning": "to celebrate", "example_cn": "我们一起庆祝妈妈的生日。", "example_en": "We celebrate Mum's birthday together.", "lesson": 12.1}, {"id": "12-2", "hanzi": "设计", "pinyin": "shèjì", "meaning": "to design", "example_cn": "这是我设计的明信片。", "example_en": "This is the postcard I designed.", "lesson": 12.1}, {"id": "12-3", "hanzi": "明信片", "pinyin": "míngxìnpiàn", "meaning": "postcard", "example_cn": "我给奶奶寄了一张明信片。", "example_en": "I sent Grandma a postcard.", "lesson": 12.1}, {"id": "12-4", "hanzi": "左上角", "pinyin": "zuǒ shàngjiǎo", "meaning": "top left corner", "example_cn": "左上角是高高的组屋。", "example_en": "In the top left corner are tall HDB flats.", "lesson": 12.1}, {"id": "12-5", "hanzi": "右上角", "pinyin": "yòu shàngjiǎo", "meaning": "top right corner", "example_cn": "右上角是樟宜机场。", "example_en": "In the top right corner is Changi Airport.", "lesson": 12.1}, {"id": "12-6", "hanzi": "右下角", "pinyin": "yòu xiàjiǎo", "meaning": "bottom right corner", "example_cn": "右下角是鱼尾狮。", "example_en": "In the bottom right corner is the Merlion.", "lesson": 12.1}, {"id": "12-7", "hanzi": "左下角", "pinyin": "zuǒ xiàjiǎo", "meaning": "bottom left corner", "example_cn": "左下角是不同种族的小朋友。", "example_en": "In the bottom left corner are children of different races.", "lesson": 12.1}, {"id": "12-8", "hanzi": "沙爹", "pinyin": "shādiē", "meaning": "satay", "example_cn": "我最喜欢吃沙爹。", "example_en": "I like eating satay the most.", "lesson": 12.1}, {"id": "12-9", "hanzi": "鱼尾狮", "pinyin": "yúwěishī", "meaning": "Merlion", "example_cn": "鱼尾狮是新加坡有名的地方。", "example_en": "The Merlion is a famous place in Singapore.", "lesson": 12.1}, {"id": "12-10", "hanzi": "不同", "pinyin": "bùtóng", "meaning": "different", "example_cn": "我们班有不同种族的同学。", "example_en": "Our class has classmates of different races.", "lesson": 12.1}, {"id": "12-11", "hanzi": "种族", "pinyin": "zhǒngzú", "meaning": "race; ethnic group", "example_cn": "新加坡有很多种族的人。", "example_en": "Singapore has people of many races.", "lesson": 12.1}, {"id": "12-12", "hanzi": "华人", "pinyin": "Huárén", "meaning": "Chinese (person)", "example_cn": "我的家人都是华人。", "example_en": "My family members are all Chinese.", "lesson": 12.1}, {"id": "12-13", "hanzi": "马来人", "pinyin": "Mǎláirén", "meaning": "Malay (person)", "example_cn": "我的邻居是马来人。", "example_en": "My neighbour is Malay.", "lesson": 12.1}, {"id": "12-14", "hanzi": "印度人", "pinyin": "Yìndùrén", "meaning": "Indian (person)", "example_cn": "我的好朋友是印度人。", "example_en": "My good friend is Indian.", "lesson": 12.1}, {"id": "12-15", "hanzi": "欧亚人", "pinyin": "Ōu-Yàrén", "meaning": "Eurasian (person)", "example_cn": "他的爸爸是欧亚人。", "example_en": "His father is Eurasian.", "lesson": 12.1}, {"id": "12-16", "hanzi": "多元", "pinyin": "duōyuán", "meaning": "diverse; multi-", "example_cn": "新加坡是个多元种族的国家。", "example_en": "Singapore is a multiracial country.", "lesson": 12.1}, {"id": "12-17", "hanzi": "国家", "pinyin": "guójiā", "meaning": "country", "example_cn": "新加坡是一个美丽的国家。", "example_en": "Singapore is a beautiful country.", "lesson": 12.1}, {"id": "12-18", "hanzi": "护照", "pinyin": "hùzhào", "meaning": "passport", "example_cn": "这是我们的护照。", "example_en": "This is our passport.", "lesson": 12.1}, {"id": "12-19", "hanzi": "中间", "pinyin": "zhōngjiān", "meaning": "middle; centre", "example_cn": "明信片的中间是国旗。", "example_en": "The national flag is in the middle of the postcard.", "lesson": 12.1}, {"id": "12-20", "hanzi": "礼物", "pinyin": "lǐwù", "meaning": "gift; present", "example_cn": "这是我送给新加坡的礼物。", "example_en": "This is my present for Singapore.", "lesson": 12.1}], "12.2": [{"id": "12-21", "hanzi": "亮晶晶", "pinyin": "liàngjīngjīng", "meaning": "sparkling; glittering", "example_cn": "天上有亮晶晶的星星。", "example_en": "There are sparkling stars in the sky.", "lesson": 12.2}, {"id": "12-22", "hanzi": "狮子", "pinyin": "shīzi", "meaning": "lion", "example_cn": "护照上有狮子和老虎的图案。", "example_en": "There are lions and tigers on the passport.", "lesson": 12.2}, {"id": "12-23", "hanzi": "老虎", "pinyin": "lǎohǔ", "meaning": "tiger", "example_cn": "动物园里有一只白老虎。", "example_en": "There is a white tiger in the zoo.", "lesson": 12.2}, {"id": "12-24", "hanzi": "图案", "pinyin": "tú'àn", "meaning": "pattern; design", "example_cn": "这件衣服的图案很漂亮。", "example_en": "The pattern on this shirt is very pretty.", "lesson": 12.2}, {"id": "12-25", "hanzi": "美丽", "pinyin": "měilì", "meaning": "beautiful", "example_cn": "新加坡是个美丽的大花园。", "example_en": "Singapore is a beautiful big garden.", "lesson": 12.2}, {"id": "12-26", "hanzi": "各种各样", "pinyin": "gè zhǒng gè yàng", "meaning": "all kinds of", "example_cn": "新加坡有各种各样的花草树木。", "example_en": "Singapore has all kinds of flowers, plants and trees.", "lesson": 12.2}, {"id": "12-27", "hanzi": "花草树木", "pinyin": "huācǎo shùmù", "meaning": "flowers, plants and trees", "example_cn": "公园里有很多花草树木。", "example_en": "There are many flowers, plants and trees in the park.", "lesson": 12.2}, {"id": "12-28", "hanzi": "生活", "pinyin": "shēnghuó", "meaning": "to live; life", "example_cn": "人们快乐地生活在一起。", "example_en": "People live happily together.", "lesson": 12.2}, {"id": "12-29", "hanzi": "喷水", "pinyin": "pēn shuǐ", "meaning": "to spout water", "example_cn": "鱼尾狮在河边不停地喷水。", "example_en": "The Merlion keeps spouting water by the river.", "lesson": 12.2}, {"id": "12-30", "hanzi": "东海岸", "pinyin": "Dōnghǎi'àn", "meaning": "East Coast", "example_cn": "周末我们去东海岸公园玩。", "example_en": "We go to East Coast Park on the weekend.", "lesson": 12.2}, {"id": "12-31", "hanzi": "野餐", "pinyin": "yěcān", "meaning": "picnic; to have a picnic", "example_cn": "人们在公园开心地野餐。", "example_en": "People have a happy picnic in the park.", "lesson": 12.2}, {"id": "12-32", "hanzi": "骑脚踏车", "pinyin": "qí jiǎotàchē", "meaning": "to ride a bicycle", "example_cn": "我喜欢在公园里骑脚踏车。", "example_en": "I like riding a bicycle in the park.", "lesson": 12.2}], "12.3": [{"id": "12-33", "hanzi": "国旗", "pinyin": "guóqí", "meaning": "national flag", "example_cn": "画的中间是国旗。", "example_en": "The national flag is in the middle of the drawing.", "lesson": 12.3}, {"id": "12-34", "hanzi": "弯弯", "pinyin": "wānwān", "meaning": "curved", "example_cn": "国旗上有弯弯的月亮。", "example_en": "There is a crescent moon on the national flag.", "lesson": 12.3}, {"id": "12-35", "hanzi": "颗", "pinyin": "kē", "meaning": "measure word for small round things", "example_cn": "国旗上还有五颗星星。", "example_en": "There are also five stars on the national flag.", "lesson": 12.3}, {"id": "12-36", "hanzi": "樟宜机场", "pinyin": "Zhāngyí Jīchǎng", "meaning": "Changi Airport", "example_cn": "樟宜机场有很多飞机。", "example_en": "There are many planes at Changi Airport.", "lesson": 12.3}, {"id": "12-37", "hanzi": "唱国歌", "pinyin": "chàng guógē", "meaning": "to sing the national anthem", "example_cn": "我们每天早上唱国歌。", "example_en": "We sing the national anthem every morning.", "lesson": 12.3}, {"id": "12-38", "hanzi": "竖起", "pinyin": "shùqǐ", "meaning": "to hold up; to raise upright", "example_cn": "小安竖起大拇指说：“画得真不错！”", "example_en": "Xiao An gave a thumbs up and said, \"Great drawing!\"", "lesson": 12.3}, {"id": "12-39", "hanzi": "大拇指", "pinyin": "dàmǔzhǐ", "meaning": "thumb", "example_cn": "他向我竖起了大拇指。", "example_en": "He gave me a thumbs up.", "lesson": 12.3}, {"id": "12-40", "hanzi": "贴", "pinyin": "tiē", "meaning": "to stick; to paste", "example_cn": "我们把画贴在墙上吧。", "example_en": "Let's stick the drawing on the wall.", "lesson": 12.3}, {"id": "12-41", "hanzi": "猜谜", "pinyin": "cāimí", "meaning": "to solve riddles", "example_cn": "我们一起来猜谜吧！", "example_en": "Let's solve riddles together!", "lesson": 12.3}, {"id": "12-42", "hanzi": "猜", "pinyin": "cāi", "meaning": "to guess", "example_cn": "请你猜一个谜语。", "example_en": "Please guess a riddle.", "lesson": 12.3}, {"id": "12-43", "hanzi": "信心", "pinyin": "xìnxīn", "meaning": "confidence", "example_cn": "弟弟很有信心地说出了答案。", "example_en": "My little brother gave the answer confidently.", "lesson": 12.3}, {"id": "12-44", "hanzi": "兴奋", "pinyin": "xīngfèn", "meaning": "excited", "example_cn": "小安兴奋地唱了起来。", "example_en": "Xiao An started singing excitedly.", "lesson": 12.3}], "12.4": [{"id": "12-45", "hanzi": "印度煎饼", "pinyin": "Yìndù jiānbǐng", "meaning": "roti prata", "example_cn": "我早餐吃了印度煎饼。", "example_en": "I ate roti prata for breakfast.", "lesson": 12.4}, {"id": "12-46", "hanzi": "农历新年", "pinyin": "Nónglì Xīnnián", "meaning": "Lunar New Year", "example_cn": "农历新年也叫春节。", "example_en": "Lunar New Year is also called the Spring Festival.", "lesson": 12.4}, {"id": "12-47", "hanzi": "开斋节", "pinyin": "Kāizhāi Jié", "meaning": "Hari Raya Puasa", "example_cn": "开斋节是马来人的节日。", "example_en": "Hari Raya Puasa is a Malay festival.", "lesson": 12.4}, {"id": "12-48", "hanzi": "屠妖节", "pinyin": "Túyāo Jié", "meaning": "Deepavali", "example_cn": "屠妖节时，小印度挂满了彩灯。", "example_en": "During Deepavali, Little India is full of coloured lights.", "lesson": 12.4}, {"id": "12-49", "hanzi": "圣诞节", "pinyin": "Shèngdàn Jié", "meaning": "Christmas", "example_cn": "圣诞节时，我们会交换礼物。", "example_en": "At Christmas, we exchange presents.", "lesson": 12.4}], "12.5": [{"id": "12-50", "hanzi": "未来", "pinyin": "wèilái", "meaning": "the future", "example_cn": "未来的新加坡多美好啊！", "example_en": "How wonderful the Singapore of the future will be!", "lesson": 12.5}, {"id": "12-51", "hanzi": "梦", "pinyin": "mèng", "meaning": "dream", "example_cn": "那天夜里，我做了一个梦。", "example_en": "That night, I had a dream.", "lesson": 12.5}, {"id": "12-52", "hanzi": "无人驾驶", "pinyin": "wúrén jiàshǐ", "meaning": "driverless; self-driving", "example_cn": "我们坐上了无人驾驶的汽车。", "example_en": "We got into a driverless car.", "lesson": 12.5}, {"id": "12-53", "hanzi": "聊天", "pinyin": "liáotiān", "meaning": "to chat", "example_cn": "我用视频跟朋友聊天。", "example_en": "I chat with my friend by video call.", "lesson": 12.5}, {"id": "12-54", "hanzi": "机器人", "pinyin": "jīqìrén", "meaning": "robot", "example_cn": "机器人为我们开门。", "example_en": "The robot opens the door for us.", "lesson": 12.5}, {"id": "12-55", "hanzi": "餐厅", "pinyin": "cāntīng", "meaning": "restaurant", "example_cn": "我们来到了一家餐厅。", "example_en": "We arrived at a restaurant.", "lesson": 12.5}, {"id": "12-56", "hanzi": "礼貌", "pinyin": "lǐmào", "meaning": "polite; manners", "example_cn": "他很有礼貌地说：“欢迎，请进！”", "example_en": "He said very politely, \"Welcome, please come in!\"", "lesson": 12.5}, {"id": "12-57", "hanzi": "选择", "pinyin": "xuǎnzé", "meaning": "to choose", "example_cn": "桌上有很多食物让我们选择。", "example_en": "There is a lot of food on the table for us to choose from.", "lesson": 12.5}, {"id": "12-58", "hanzi": "秋千", "pinyin": "qiūqiān", "meaning": "swing", "example_cn": "我们开心地荡秋千。", "example_en": "We happily play on the swing.", "lesson": 12.5}, {"id": "12-59", "hanzi": "期待", "pinyin": "qīdài", "meaning": "to look forward to", "example_cn": "我期待它早日到来。", "example_en": "I look forward to it coming soon.", "lesson": 12.5}], "13.1": [{"id": "13-0", "hanzi": "动物", "pinyin": "dòngwù", "meaning": "animal", "example_cn": "你最喜欢什么动物？", "example_en": "What is your favourite animal?", "lesson": 13.1}, {"id": "13-1", "hanzi": "世界", "pinyin": "shìjiè", "meaning": "world", "example_cn": "动物世界真有趣！", "example_en": "The animal world is so interesting!", "lesson": 13.1}, {"id": "13-2", "hanzi": "地图", "pinyin": "dìtú", "meaning": "map", "example_cn": "我们看着地图找路。", "example_en": "We look at the map to find the way.", "lesson": 13.1}, {"id": "13-3", "hanzi": "穿山甲", "pinyin": "chuānshānjiǎ", "meaning": "pangolin", "example_cn": "穿山甲身上有硬硬的鳞片。", "example_en": "A pangolin has hard scales on its body.", "lesson": 13.1}, {"id": "13-4", "hanzi": "果子狸", "pinyin": "guǒzilí", "meaning": "civet", "example_cn": "果子狸晚上才出来找食物。", "example_en": "Civets only come out to look for food at night.", "lesson": 13.1}, {"id": "13-5", "hanzi": "做客", "pinyin": "zuòkè", "meaning": "to be a guest; to visit", "example_cn": "熊伯伯请它们来做客。", "example_en": "Uncle Bear invited them to visit.", "lesson": 13.1}, {"id": "13-6", "hanzi": "瀑布", "pinyin": "pùbù", "meaning": "waterfall", "example_cn": "左边有个很大的瀑布。", "example_en": "There is a big waterfall on the left.", "lesson": 13.1}, {"id": "13-7", "hanzi": "沿着", "pinyin": "yánzhe", "meaning": "along", "example_cn": "沿着小路往前走，就能看到瀑布。", "example_en": "Walk along the path and you will see the waterfall.", "lesson": 13.1}, {"id": "13-8", "hanzi": "往前走", "pinyin": "wǎng qián zǒu", "meaning": "to walk straight ahead", "example_cn": "你再往前走，右边就是竹林。", "example_en": "Walk on ahead and the bamboo grove is on the right.", "lesson": 13.1}, {"id": "13-9", "hanzi": "竹林", "pinyin": "zhúlín", "meaning": "bamboo grove", "example_cn": "熊猫住在竹林里。", "example_en": "The panda lives in the bamboo grove.", "lesson": 13.1}, {"id": "13-10", "hanzi": "湖", "pinyin": "hú", "meaning": "lake", "example_cn": "湖里住着鱼和虾。", "example_en": "Fish and shrimps live in the lake.", "lesson": 13.1}, {"id": "13-11", "hanzi": "草丛", "pinyin": "cǎocóng", "meaning": "clump of grass", "example_cn": "湖的前面是草丛。", "example_en": "In front of the lake is a clump of grass.", "lesson": 13.1}, {"id": "13-12", "hanzi": "毛毛虫", "pinyin": "máomaochóng", "meaning": "caterpillar", "example_cn": "毛毛虫会变成蝴蝶。", "example_en": "A caterpillar turns into a butterfly.", "lesson": 13.1}, {"id": "13-13", "hanzi": "森林", "pinyin": "sēnlín", "meaning": "forest", "example_cn": "湖的左边是森林。", "example_en": "On the left of the lake is a forest.", "lesson": 13.1}, {"id": "13-14", "hanzi": "鹅", "pinyin": "é", "meaning": "goose", "example_cn": "湖里有一只白白的鹅。", "example_en": "There is a white goose in the lake.", "lesson": 13.1}, {"id": "13-15", "hanzi": "虾", "pinyin": "xiā", "meaning": "shrimp", "example_cn": "水池里有很多小虾。", "example_en": "There are many little shrimps in the pond.", "lesson": 13.1}, {"id": "13-16", "hanzi": "青蛙", "pinyin": "qīngwā", "meaning": "frog", "example_cn": "荷叶上坐着一只青蛙。", "example_en": "A frog is sitting on the lotus leaf.", "lesson": 13.1}], "13.2": [{"id": "13-17", "hanzi": "山坡", "pinyin": "shānpō", "meaning": "hillside; slope", "example_cn": "爬上山坡，就到熊住的山洞了。", "example_en": "Climb up the slope and you reach the cave where the bear lives.", "lesson": 13.2}, {"id": "13-18", "hanzi": "山顶", "pinyin": "shāndǐng", "meaning": "hilltop", "example_cn": "山顶有棵大树。", "example_en": "There is a big tree on the hilltop.", "lesson": 13.2}, {"id": "13-19", "hanzi": "山洞", "pinyin": "shāndòng", "meaning": "cave", "example_cn": "山洞里黑黑的。", "example_en": "It is dark inside the cave.", "lesson": 13.2}, {"id": "13-20", "hanzi": "沙滩", "pinyin": "shātān", "meaning": "beach", "example_cn": "我们在沙滩上堆沙堡。", "example_en": "We build sandcastles on the beach.", "lesson": 13.2}, {"id": "13-21", "hanzi": "水池", "pinyin": "shuǐchí", "meaning": "pond", "example_cn": "房子的前面有个水池。", "example_en": "There is a pond in front of the house.", "lesson": 13.2}, {"id": "13-22", "hanzi": "养", "pinyin": "yǎng", "meaning": "to raise; to keep (animals)", "example_cn": "水池里养着鱼和虾。", "example_en": "Fish and shrimps are kept in the pond.", "lesson": 13.2}, {"id": "13-23", "hanzi": "狼", "pinyin": "láng", "meaning": "wolf", "example_cn": "森林里住着狐狸和狼。", "example_en": "Foxes and wolves live in the forest.", "lesson": 13.2}, {"id": "13-24", "hanzi": "熊", "pinyin": "xióng", "meaning": "bear", "example_cn": "山洞里住着一只熊。", "example_en": "A bear lives in the cave.", "lesson": 13.2}, {"id": "13-25", "hanzi": "熊猫", "pinyin": "xióngmāo", "meaning": "panda", "example_cn": "走过小桥，就到熊猫住的竹林了。", "example_en": "Cross the little bridge and you reach the bamboo grove where the panda lives.", "lesson": 13.2}], "13.3": [{"id": "13-26", "hanzi": "动物园", "pinyin": "dòngwùyuán", "meaning": "zoo", "example_cn": "我们来到动物园玩找动物的游戏。", "example_en": "We came to the zoo to play a find-the-animal game.", "lesson": 13.3}, {"id": "13-27", "hanzi": "小组", "pinyin": "xiǎozǔ", "meaning": "group", "example_cn": "老师给每个小组一张地图。", "example_en": "The teacher gave each group a map.", "lesson": 13.3}, {"id": "13-28", "hanzi": "必须", "pinyin": "bìxū", "meaning": "must", "example_cn": "每组必须找到指定的动物。", "example_en": "Each group must find the assigned animal.", "lesson": 13.3}, {"id": "13-29", "hanzi": "拍照", "pinyin": "pāizhào", "meaning": "to take a photo", "example_cn": "我们给袋鼠拍照。", "example_en": "We take a photo of the kangaroo.", "lesson": 13.3}, {"id": "13-30", "hanzi": "起点", "pinyin": "qǐdiǎn", "meaning": "starting point", "example_cn": "拍完照片，我们要回到起点。", "example_en": "After taking photos, we have to go back to the starting point.", "lesson": 13.3}, {"id": "13-31", "hanzi": "袋鼠", "pinyin": "dàishǔ", "meaning": "kangaroo", "example_cn": "我们小组要找的是袋鼠。", "example_en": "Our group has to find the kangaroo.", "lesson": 13.3}, {"id": "13-32", "hanzi": "讨论", "pinyin": "tǎolùn", "meaning": "to discuss", "example_cn": "我们讨论了一会儿，就出发了。", "example_en": "We discussed for a while and then set off.", "lesson": 13.3}, {"id": "13-33", "hanzi": "路线", "pinyin": "lùxiàn", "meaning": "route", "example_cn": "我们决定了一条路线。", "example_en": "We decided on a route.", "lesson": 13.3}, {"id": "13-34", "hanzi": "出发", "pinyin": "chūfā", "meaning": "to set off", "example_cn": "我们八点出发去动物园。", "example_en": "We set off for the zoo at eight o'clock.", "lesson": 13.3}, {"id": "13-35", "hanzi": "组长", "pinyin": "zǔzhǎng", "meaning": "group leader", "example_cn": "康康是我们的组长。", "example_en": "Kangkang is our group leader.", "lesson": 13.3}, {"id": "13-36", "hanzi": "猴子", "pinyin": "hóuzi", "meaning": "monkey", "example_cn": "右边是猴子住的小山。", "example_en": "On the right is the hill where the monkeys live.", "lesson": 13.3}, {"id": "13-37", "hanzi": "带领", "pinyin": "dàilǐng", "meaning": "to lead", "example_cn": "在康康的带领下，我们很快找到了袋鼠。", "example_en": "Led by Kangkang, we quickly found the kangaroo.", "lesson": 13.3}, {"id": "13-38", "hanzi": "任务", "pinyin": "rènwu", "meaning": "task", "example_cn": "我们拍了照，完成了任务。", "example_en": "We took photos and completed the task.", "lesson": 13.3}, {"id": "13-39", "hanzi": "急忙", "pinyin": "jímáng", "meaning": "hurriedly; in a rush", "example_cn": "我们急忙赶回起点。", "example_en": "We hurried back to the starting point.", "lesson": 13.3}, {"id": "13-40", "hanzi": "孔雀", "pinyin": "kǒngquè", "meaning": "peacock", "example_cn": "我们看到一只漂亮的孔雀。", "example_en": "We saw a beautiful peacock.", "lesson": 13.3}, {"id": "13-41", "hanzi": "忘", "pinyin": "wàng", "meaning": "to forget", "example_cn": "我们追着孔雀拍照，结果忘了时间。", "example_en": "We chased the peacock to take photos and forgot the time.", "lesson": 13.3}, {"id": "13-42", "hanzi": "最后一名", "pinyin": "zuìhòu yì míng", "meaning": "last place", "example_cn": "赛跑时，我跑了最后一名。", "example_en": "I came last in the race.", "lesson": 13.3}, {"id": "13-43", "hanzi": "虽然", "pinyin": "suīrán", "meaning": "although", "example_cn": "我们虽然是最后一名，但是仍然很开心。", "example_en": "Although we came last, we were still very happy.", "lesson": 13.3}, {"id": "13-44", "hanzi": "仍然", "pinyin": "réngrán", "meaning": "still", "example_cn": "比赛输了，他仍然笑得很开心。", "example_en": "He lost the match but was still smiling happily.", "lesson": 13.3}], "13.5": [{"id": "13-45", "hanzi": "天桥", "pinyin": "tiānqiáo", "meaning": "overhead bridge; overpass", "example_cn": "人们会在高速公路的上方建一座天桥。", "example_en": "People will build an overpass above the expressway.", "lesson": 13.5}, {"id": "13-46", "hanzi": "自由自在", "pinyin": "zìyóu-zìzài", "meaning": "free and easy", "example_cn": "动物们在森林里自由自在地生活。", "example_en": "The animals live freely in the forest.", "lesson": 13.5}, {"id": "13-47", "hanzi": "高速公路", "pinyin": "gāosù gōnglù", "meaning": "expressway; highway", "example_cn": "人们正在建一条高速公路。", "example_en": "People are building an expressway.", "lesson": 13.5}, {"id": "13-48", "hanzi": "担心", "pinyin": "dānxīn", "meaning": "to worry", "example_cn": "动物们都十分担心森林会被分隔开来。", "example_en": "The animals were all very worried that the forest would be split apart.", "lesson": 13.5}, {"id": "13-49", "hanzi": "舍不得", "pinyin": "shěbude", "meaning": "to hate to part with", "example_cn": "我真舍不得你啊！", "example_en": "I really hate to part with you!", "lesson": 13.5}, {"id": "13-50", "hanzi": "蝙蝠", "pinyin": "biānfú", "meaning": "bat", "example_cn": "这时，蝙蝠飞了过来。", "example_en": "Just then, the bat flew over.", "lesson": 13.5}, {"id": "13-51", "hanzi": "一模一样", "pinyin": "yì mú yí yàng", "meaning": "exactly the same", "example_cn": "天桥上的环境跟原本的森林一模一样。", "example_en": "The environment on the bridge is exactly the same as the original forest.", "lesson": 13.5}], "14.1": [{"id": "14-0", "hanzi": "奇妙", "pinyin": "qímiào", "meaning": "wonderful; marvellous", "example_cn": "大自然真奇妙！", "example_en": "Nature is so wonderful!", "lesson": 14.1}, {"id": "14-1", "hanzi": "身体", "pinyin": "shēntǐ", "meaning": "body", "example_cn": "我的猫身体胖胖的。", "example_en": "My cat has a chubby body.", "lesson": 14.1}, {"id": "14-2", "hanzi": "胖胖", "pinyin": "pàngpàng", "meaning": "chubby; plump", "example_cn": "小猪的肚子胖胖的。", "example_en": "The piglet's tummy is chubby.", "lesson": 14.1}, {"id": "14-3", "hanzi": "软软", "pinyin": "ruǎnruǎn", "meaning": "soft", "example_cn": "小狗的毛软软的。", "example_en": "The puppy's fur is soft.", "lesson": 14.1}, {"id": "14-4", "hanzi": "滑滑", "pinyin": "huáhuá", "meaning": "smooth; silky", "example_cn": "兔子的毛滑滑的。", "example_en": "The rabbit's fur is smooth.", "lesson": 14.1}, {"id": "14-5", "hanzi": "眼圈", "pinyin": "yǎnquān", "meaning": "ring around the eye", "example_cn": "熊猫有大大的黑眼圈。", "example_en": "The panda has big black rings around its eyes.", "lesson": 14.1}, {"id": "14-6", "hanzi": "胡子", "pinyin": "húzi", "meaning": "whiskers; beard", "example_cn": "爷爷的胡子白白的。", "example_en": "Grandpa's beard is white.", "lesson": 14.1}, {"id": "14-7", "hanzi": "灰色", "pinyin": "huīsè", "meaning": "grey", "example_cn": "小猫的身体是灰色的。", "example_en": "The kitten's body is grey.", "lesson": 14.1}, {"id": "14-8", "hanzi": "嘴边", "pinyin": "zuǐbiān", "meaning": "around the mouth", "example_cn": "小猫嘴边有长长的胡子。", "example_en": "The kitten has long whiskers around its mouth.", "lesson": 14.1}, {"id": "14-9", "hanzi": "周围", "pinyin": "zhōuwéi", "meaning": "around; surrounding", "example_cn": "熊猫的眼睛周围是黑色的。", "example_en": "It is black around the panda's eyes.", "lesson": 14.1}, {"id": "14-10", "hanzi": "睡醒", "pinyin": "shuìxǐng", "meaning": "to wake up", "example_cn": "弟弟睡醒了就要喝牛奶。", "example_en": "My little brother wants milk as soon as he wakes up.", "lesson": 14.1}, {"id": "14-11", "hanzi": "伸懒腰", "pinyin": "shēn lǎnyāo", "meaning": "to stretch oneself", "example_cn": "小猫睡醒时会伸懒腰。", "example_en": "The kitten stretches when it wakes up.", "lesson": 14.1}, {"id": "14-12", "hanzi": "打哈欠", "pinyin": "dǎ hāqian", "meaning": "to yawn", "example_cn": "弟弟困了，一直在打哈欠。", "example_en": "My little brother is sleepy and keeps yawning.", "lesson": 14.1}, {"id": "14-13", "hanzi": "舔", "pinyin": "tiǎn", "meaning": "to lick", "example_cn": "小猫在舔爪子。", "example_en": "The kitten is licking its paw.", "lesson": 14.1}, {"id": "14-14", "hanzi": "爪子", "pinyin": "zhuǎzi", "meaning": "claw; paw", "example_cn": "它用爪子挖一个小水坑。", "example_en": "It digs a small puddle with its paws.", "lesson": 14.1}, {"id": "14-15", "hanzi": "声音", "pinyin": "shēngyīn", "meaning": "sound; voice", "example_cn": "听到我的声音时，它会跑出来。", "example_en": "When it hears my voice, it runs out.", "lesson": 14.1}, {"id": "14-16", "hanzi": "钻", "pinyin": "zuān", "meaning": "to squeeze out/into", "example_cn": "小猫从床底下钻出来。", "example_en": "The kitten squeezes out from under the bed.", "lesson": 14.1}, {"id": "14-17", "hanzi": "扑", "pinyin": "pū", "meaning": "to pounce; to throw oneself at", "example_cn": "它扑到我的身上。", "example_en": "It pounces onto me.", "lesson": 14.1}], "14.2": [{"id": "14-18", "hanzi": "兔子", "pinyin": "tùzi", "meaning": "rabbit", "example_cn": "兔子的耳朵很长。", "example_en": "The rabbit's ears are very long.", "lesson": 14.2}, {"id": "14-19", "hanzi": "耳朵", "pinyin": "ěrduo", "meaning": "ear", "example_cn": "兔子的耳朵尖尖的。", "example_en": "The rabbit's ears are pointed.", "lesson": 14.2}, {"id": "14-20", "hanzi": "饿", "pinyin": "è", "meaning": "hungry", "example_cn": "小兔子饿了。", "example_en": "The little rabbit is hungry.", "lesson": 14.2}, {"id": "14-21", "hanzi": "主人", "pinyin": "zhǔrén", "meaning": "owner; master", "example_cn": "主人带小狗去公园玩。", "example_en": "The owner takes the puppy to play in the park.", "lesson": 14.2}, {"id": "14-22", "hanzi": "喂", "pinyin": "wèi", "meaning": "to feed", "example_cn": "主人喂它吃萝卜。", "example_en": "Its owner feeds it carrots.", "lesson": 14.2}, {"id": "14-23", "hanzi": "萝卜", "pinyin": "luóbo", "meaning": "radish; carrot", "example_cn": "兔子最爱吃萝卜。", "example_en": "Rabbits love eating carrots.", "lesson": 14.2}, {"id": "14-24", "hanzi": "吃饱", "pinyin": "chī bǎo", "meaning": "to eat one's fill", "example_cn": "小狗吃饱了就睡觉。", "example_en": "The puppy sleeps once it has eaten its fill.", "lesson": 14.2}, {"id": "14-25", "hanzi": "散步", "pinyin": "sànbù", "meaning": "to take a walk", "example_cn": "主人带小狗去散步。", "example_en": "The owner takes the puppy for a walk.", "lesson": 14.2}], "14.3": [{"id": "14-26", "hanzi": "可爱", "pinyin": "kě'ài", "meaning": "cute; lovely", "example_cn": "大熊猫长得很可爱。", "example_en": "The giant panda looks very cute.", "lesson": 14.3}, {"id": "14-27", "hanzi": "尾巴", "pinyin": "wěiba", "meaning": "tail", "example_cn": "大熊猫的尾巴短短的。", "example_en": "The giant panda's tail is short.", "lesson": 14.3}, {"id": "14-28", "hanzi": "却", "pinyin": "què", "meaning": "but; yet", "example_cn": "它的身体是白色的，四条腿却是黑色的。", "example_en": "Its body is white, but its four legs are black.", "lesson": 14.3}, {"id": "14-29", "hanzi": "食物", "pinyin": "shíwù", "meaning": "food", "example_cn": "大熊猫最喜欢的食物是竹子。", "example_en": "The giant panda's favourite food is bamboo.", "lesson": 14.3}, {"id": "14-30", "hanzi": "咬断", "pinyin": "yǎoduàn", "meaning": "to bite through", "example_cn": "熊猫先把竹子咬断。", "example_en": "The panda first bites through the bamboo.", "lesson": 14.3}, {"id": "14-31", "hanzi": "食量", "pinyin": "shíliàng", "meaning": "appetite; amount of food eaten", "example_cn": "大熊猫的食量可大了。", "example_en": "The giant panda has a huge appetite.", "lesson": 14.3}, {"id": "14-32", "hanzi": "公斤", "pinyin": "gōngjīn", "meaning": "kilogram", "example_cn": "大熊猫一天要吃十公斤左右的竹子。", "example_en": "A giant panda eats about ten kilograms of bamboo a day.", "lesson": 14.3}, {"id": "14-33", "hanzi": "够", "pinyin": "gòu", "meaning": "enough", "example_cn": "这些竹子够它吃一天。", "example_en": "This bamboo is enough for it to eat for a day.", "lesson": 14.3}, {"id": "14-34", "hanzi": "有趣", "pinyin": "yǒuqù", "meaning": "interesting; fun", "example_cn": "大熊猫喝水的样子很有趣。", "example_en": "The way a giant panda drinks water is very fun.", "lesson": 14.3}, {"id": "14-35", "hanzi": "挖", "pinyin": "wā", "meaning": "to dig", "example_cn": "小狗在花园里挖洞。", "example_en": "The puppy is digging a hole in the garden.", "lesson": 14.3}, {"id": "14-36", "hanzi": "咕噜咕噜", "pinyin": "gūlū gūlū", "meaning": "gulp gulp (sound of drinking)", "example_cn": "它咕噜咕噜地喝起水来。", "example_en": "It started drinking water, gulp gulp.", "lesson": 14.3}, {"id": "14-37", "hanzi": "肚子", "pinyin": "dùzi", "meaning": "belly; tummy", "example_cn": "它喝得肚子圆圆的。", "example_en": "It drinks until its belly is round.", "lesson": 14.3}, {"id": "14-38", "hanzi": "躺", "pinyin": "tǎng", "meaning": "to lie down", "example_cn": "熊猫在河边躺了几个小时。", "example_en": "The panda lay by the river for a few hours.", "lesson": 14.3}, {"id": "14-39", "hanzi": "慢慢", "pinyin": "mànmàn", "meaning": "slowly", "example_cn": "它才慢慢地爬起来。", "example_en": "Only then does it slowly get up.", "lesson": 14.3}, {"id": "14-40", "hanzi": "摆动", "pinyin": "bǎidòng", "meaning": "to sway; to swing", "example_cn": "它摆动着胖胖的身体走了。", "example_en": "It walked off, swaying its chubby body.", "lesson": 14.3}], "14.4": [{"id": "14-41", "hanzi": "井底之蛙", "pinyin": "jǐng dǐ zhī wā", "meaning": "a frog at the bottom of a well (a narrow-minded person)", "example_cn": "我们要多看书，不要做井底之蛙。", "example_en": "We should read more and not be like a frog at the bottom of a well.", "lesson": 14.4}, {"id": "14-42", "hanzi": "大海", "pinyin": "dàhǎi", "meaning": "the sea", "example_cn": "你见过大海吗？", "example_en": "Have you ever seen the sea?", "lesson": 14.4}, {"id": "14-43", "hanzi": "广阔", "pinyin": "guǎngkuò", "meaning": "vast; wide", "example_cn": "大海非常广阔。", "example_en": "The sea is very vast.", "lesson": 14.4}], "14.5": [{"id": "14-44", "hanzi": "假如", "pinyin": "jiǎrú", "meaning": "if; suppose", "example_cn": "假如我可以变，我想变成一只小鸟。", "example_en": "If I could change, I would turn into a little bird.", "lesson": 14.5}, {"id": "14-45", "hanzi": "希望", "pinyin": "xīwàng", "meaning": "to hope; to wish", "example_cn": "我希望自己变成一只蜻蜓。", "example_en": "I wish I could turn into a dragonfly.", "lesson": 14.5}, {"id": "14-46", "hanzi": "蜻蜓", "pinyin": "qīngtíng", "meaning": "dragonfly", "example_cn": "一只蜻蜓停在叶子上。", "example_en": "A dragonfly landed on a leaf.", "lesson": 14.5}, {"id": "14-47", "hanzi": "害虫", "pinyin": "hàichóng", "meaning": "pest; harmful insect", "example_cn": "哪里有害虫，我就飞到哪里去。", "example_en": "Wherever there are pests, I will fly there.", "lesson": 14.5}, {"id": "14-48", "hanzi": "捉迷藏", "pinyin": "zhuō mícáng", "meaning": "hide-and-seek", "example_cn": "我和鱼儿一起玩捉迷藏。", "example_en": "I play hide-and-seek with the fish.", "lesson": 14.5}, {"id": "14-49", "hanzi": "植物", "pinyin": "zhíwù", "meaning": "plant", "example_cn": "植物需要阳光和水。", "example_en": "Plants need sunlight and water.", "lesson": 14.5}, {"id": "14-50", "hanzi": "泥土", "pinyin": "nítǔ", "meaning": "soil; earth", "example_cn": "蚯蚓在泥土里钻来钻去。", "example_en": "Earthworms wriggle through the soil.", "lesson": 14.5}, {"id": "14-51", "hanzi": "农夫", "pinyin": "nóngfū", "meaning": "farmer", "example_cn": "我帮农夫翻松泥土。", "example_en": "I help the farmer loosen the soil.", "lesson": 14.5}, {"id": "14-52", "hanzi": "称赞", "pinyin": "chēngzàn", "meaning": "to praise", "example_cn": "老师称赞我的字写得好。", "example_en": "The teacher praised my good handwriting.", "lesson": 14.5}, {"id": "14-53", "hanzi": "好帮手", "pinyin": "hǎo bāngshǒu", "meaning": "good helper", "example_cn": "我是妈妈的好帮手。", "example_en": "I am Mum's good helper.", "lesson": 14.5}], "15.1": [{"id": "15-0", "hanzi": "华文", "pinyin": "Huáwén", "meaning": "Chinese language", "example_cn": "我每天都学华文。", "example_en": "I study Chinese every day.", "lesson": 15.1}, {"id": "15-1", "hanzi": "欢乐", "pinyin": "huānlè", "meaning": "happy; joyful", "example_cn": "我们是欢乐的伙伴。", "example_en": "We are happy companions.", "lesson": 15.1}, {"id": "15-2", "hanzi": "伙伴", "pinyin": "huǒbàn", "meaning": "partner; companion", "example_cn": "他是我的好伙伴。", "example_en": "He is my good companion.", "lesson": 15.1}, {"id": "15-3", "hanzi": "课堂", "pinyin": "kètáng", "meaning": "classroom; class", "example_cn": "小小的课堂，大大的舞台。", "example_en": "A small classroom, a big stage.", "lesson": 15.1}, {"id": "15-4", "hanzi": "舞台", "pinyin": "wǔtái", "meaning": "stage", "example_cn": "她站在舞台上唱歌。", "example_en": "She stands on the stage and sings.", "lesson": 15.1}, {"id": "15-5", "hanzi": "分享", "pinyin": "fēnxiǎng", "meaning": "to share", "example_cn": "我和同学分享我的故事书。", "example_en": "I share my storybook with my classmates.", "lesson": 15.1}, {"id": "15-6", "hanzi": "童年", "pinyin": "tóngnián", "meaning": "childhood", "example_cn": "我有一个快乐的童年。", "example_en": "I have a happy childhood.", "lesson": 15.1}, {"id": "15-7", "hanzi": "方块", "pinyin": "fāngkuài", "meaning": "square; block", "example_cn": "华文字是小小的方块字。", "example_en": "Chinese characters are small square characters.", "lesson": 15.1}, {"id": "15-8", "hanzi": "力量", "pinyin": "lìliang", "meaning": "strength; power", "example_cn": "大家一起努力，力量就大了。", "example_en": "When everyone works together, we become stronger.", "lesson": 15.1}, {"id": "15-9", "hanzi": "神奇", "pinyin": "shénqí", "meaning": "magical; amazing", "example_cn": "书里有一个神奇的世界。", "example_en": "There is a magical world inside books.", "lesson": 15.1}, {"id": "15-10", "hanzi": "成长", "pinyin": "chéngzhǎng", "meaning": "to grow up", "example_cn": "我们在学习中成长。", "example_en": "We grow up through learning.", "lesson": 15.1}, {"id": "15-11", "hanzi": "列车", "pinyin": "lièchē", "meaning": "train", "example_cn": "我们跳上欢乐列车。", "example_en": "We jump onto the happy train.", "lesson": 15.1}, {"id": "15-12", "hanzi": "精彩", "pinyin": "jīngcǎi", "meaning": "wonderful; brilliant", "example_cn": "这场表演真精彩！", "example_en": "This performance is brilliant!", "lesson": 15.1}, {"id": "15-13", "hanzi": "陪伴", "pinyin": "péibàn", "meaning": "to accompany; company", "example_cn": "谢谢你一直陪伴我。", "example_en": "Thank you for always keeping me company.", "lesson": 15.1}, {"id": "15-14", "hanzi": "永远", "pinyin": "yǒngyuǎn", "meaning": "forever; always", "example_cn": "我们永远是好朋友。", "example_en": "We will always be good friends.", "lesson": 15.1}, {"id": "15-15", "hanzi": "小偷", "pinyin": "xiǎotōu", "meaning": "thief", "example_cn": "小偷晚上去偷东西。", "example_en": "The thief goes to steal things at night.", "lesson": 15.1}, {"id": "15-16", "hanzi": "偷", "pinyin": "tōu", "meaning": "to steal", "example_cn": "偷东西是不对的。", "example_en": "Stealing is wrong.", "lesson": 15.1}, {"id": "15-17", "hanzi": "欢迎", "pinyin": "huānyíng", "meaning": "welcome", "example_cn": "欢迎你来我家玩！", "example_en": "Welcome to my home!", "lesson": 15.1}, {"id": "15-18", "hanzi": "窗口", "pinyin": "chuāngkǒu", "meaning": "window", "example_cn": "他爬进窗口的时候，听到有人说话。", "example_en": "When he climbed in through the window, he heard someone talking.", "lesson": 15.1}, {"id": "15-19", "hanzi": "吓了一跳", "pinyin": "xiàle yí tiào", "meaning": "to get a fright", "example_cn": "听到声音，他吓了一跳。", "example_en": "He got a fright when he heard the voice.", "lesson": 15.1}], "15.2": [{"id": "15-20", "hanzi": "腿", "pinyin": "tuǐ", "meaning": "leg", "example_cn": "他吓得两腿发软。", "example_en": "He was so scared his legs went weak.", "lesson": 15.2}, {"id": "15-21", "hanzi": "发软", "pinyin": "fāruǎn", "meaning": "to go weak", "example_cn": "我跑完步，两条腿都发软了。", "example_en": "After running, both my legs went weak.", "lesson": 15.2}, {"id": "15-22", "hanzi": "冒出", "pinyin": "màochū", "meaning": "to break out (sweat)", "example_cn": "他痛得冒出冷汗。", "example_en": "He was in so much pain he broke out in a cold sweat.", "lesson": 15.2}, {"id": "15-23", "hanzi": "冷汗", "pinyin": "lěnghàn", "meaning": "cold sweat", "example_cn": "他吓得一身冷汗。", "example_en": "He was so scared he broke into a cold sweat.", "lesson": 15.2}, {"id": "15-24", "hanzi": "全身", "pinyin": "quánshēn", "meaning": "whole body", "example_cn": "下雨了，我全身都湿了。", "example_en": "It rained and my whole body got wet.", "lesson": 15.2}, {"id": "15-25", "hanzi": "发抖", "pinyin": "fādǒu", "meaning": "to tremble; to shiver", "example_cn": "天气太冷，他冷得发抖。", "example_en": "It was too cold and he shivered.", "lesson": 15.2}, {"id": "15-26", "hanzi": "逃走", "pinyin": "táozǒu", "meaning": "to run away", "example_cn": "小偷赶快逃走了。", "example_en": "The thief quickly ran away.", "lesson": 15.2}, {"id": "15-27", "hanzi": "礼堂", "pinyin": "lǐtáng", "meaning": "assembly hall", "example_cn": "我们在礼堂看表演。", "example_en": "We watch a performance in the hall.", "lesson": 15.2}, {"id": "15-28", "hanzi": "表演", "pinyin": "biǎoyǎn", "meaning": "to perform; performance", "example_cn": "同学们在台上表演跳舞。", "example_en": "The students are performing a dance on stage.", "lesson": 15.2}, {"id": "15-29", "hanzi": "痛", "pinyin": "tòng", "meaning": "painful; to hurt", "example_cn": "我的牙齿很痛。", "example_en": "My tooth hurts a lot.", "lesson": 15.2}, {"id": "15-30", "hanzi": "赶快", "pinyin": "gǎnkuài", "meaning": "quickly; hurry", "example_cn": "下雨了，我们赶快回家。", "example_en": "It's raining, let's hurry home.", "lesson": 15.2}, {"id": "15-31", "hanzi": "蚂蚁", "pinyin": "mǎyǐ", "meaning": "ant", "example_cn": "他急得像热锅上的蚂蚁。", "example_en": "He was as anxious as an ant on a hot pan.", "lesson": 15.2}, {"id": "15-32", "hanzi": "蜜蜂", "pinyin": "mìfēng", "meaning": "bee", "example_cn": "他忙得像花丛中的蜜蜂。", "example_en": "He was as busy as a bee among the flowers.", "lesson": 15.2}], "15.3": [{"id": "15-33", "hanzi": "假期", "pinyin": "jiàqī", "meaning": "holiday", "example_cn": "假期里，妈妈带他去参加写字班。", "example_en": "During the holidays, Mum took him to a writing class.", "lesson": 15.3}, {"id": "15-34", "hanzi": "参加", "pinyin": "cānjiā", "meaning": "to take part in; to join", "example_cn": "我参加了学校的华文营。", "example_en": "I took part in the school's Chinese camp.", "lesson": 15.3}, {"id": "15-35", "hanzi": "认真", "pinyin": "rènzhēn", "meaning": "serious; careful; conscientious", "example_cn": "他平时写字不认真。", "example_en": "He usually doesn't write carefully.", "lesson": 15.3}, {"id": "15-36", "hanzi": "笔画", "pinyin": "bǐhuà", "meaning": "stroke (of a character)", "example_cn": "老师让同学们练习写笔画。", "example_en": "The teacher had the students practise writing strokes.", "lesson": 15.3}, {"id": "15-37", "hanzi": "简单", "pinyin": "jiǎndān", "meaning": "simple; easy", "example_cn": "月坡心想：这太简单了！", "example_en": "Yuepo thought: This is too easy!", "lesson": 15.3}, {"id": "15-38", "hanzi": "座位", "pinyin": "zuòwèi", "meaning": "seat", "example_cn": "他跑回座位。", "example_en": "He ran back to his seat.", "lesson": 15.3}, {"id": "15-39", "hanzi": "偷偷", "pinyin": "tōutōu", "meaning": "secretly; stealthily", "example_cn": "他偷偷地拿出一本漫画。", "example_en": "He secretly took out a comic book.", "lesson": 15.3}, {"id": "15-40", "hanzi": "漫画", "pinyin": "mànhuà", "meaning": "comic", "example_cn": "弟弟最爱看漫画。", "example_en": "My little brother loves reading comics the most.", "lesson": 15.3}, {"id": "15-41", "hanzi": "交作业", "pinyin": "jiāo zuòyè", "meaning": "to hand in homework", "example_cn": "小安交作业时看到了月坡的名字。", "example_en": "Xiao An saw Yuepo's name when handing in his homework.", "lesson": 15.3}, {"id": "15-42", "hanzi": "忍不住", "pinyin": "rěn bu zhù", "meaning": "cannot help (doing)", "example_cn": "她忍不住笑出了声。", "example_en": "She couldn't help laughing out loud.", "lesson": 15.3}, {"id": "15-43", "hanzi": "哈哈大笑", "pinyin": "hāhā dàxiào", "meaning": "to laugh heartily", "example_cn": "同学们听了都哈哈大笑起来。", "example_en": "The classmates all burst out laughing.", "lesson": 15.3}, {"id": "15-44", "hanzi": "哎呀", "pinyin": "āiyā", "meaning": "oh dear!", "example_cn": "哎呀，我忘记带书了！", "example_en": "Oh dear, I forgot to bring my book!", "lesson": 15.3}, {"id": "15-45", "hanzi": "钻", "pinyin": "zuān", "meaning": "to burrow; to squeeze into", "example_cn": "他真想在地上挖个洞钻进去。", "example_en": "He really wanted to dig a hole in the ground and crawl in.", "lesson": 15.3}, {"id": "15-46", "hanzi": "闹笑话", "pinyin": "nào xiàohua", "meaning": "to make a fool of oneself", "example_cn": "写字不认真就会闹笑话。", "example_en": "If you don't write carefully, you will make a fool of yourself.", "lesson": 15.3}, {"id": "15-47", "hanzi": "不敢", "pinyin": "bù gǎn", "meaning": "dare not", "example_cn": "他以后写字再也不敢马虎了。", "example_en": "He never dared to be careless with his writing again.", "lesson": 15.3}, {"id": "15-48", "hanzi": "马虎", "pinyin": "mǎhu", "meaning": "careless", "example_cn": "做功课不可以马虎。", "example_en": "You must not be careless with your homework.", "lesson": 15.3}], "15.4": [{"id": "15-49", "hanzi": "屋顶", "pinyin": "wūdǐng", "meaning": "roof", "example_cn": "“家”字的点，像尖尖的屋顶。", "example_en": "The dot in the character \"jia\" looks like a pointed roof.", "lesson": 15.4}], "15.5": [{"id": "15-50", "hanzi": "词汇", "pinyin": "cíhuì", "meaning": "vocabulary", "example_cn": "华语的词汇十分丰富。", "example_en": "Chinese has a very rich vocabulary.", "lesson": 15.5}, {"id": "15-51", "hanzi": "丰富", "pinyin": "fēngfù", "meaning": "rich; plentiful", "example_cn": "图书馆里的书很丰富。", "example_en": "The library has a rich collection of books.", "lesson": 15.5}, {"id": "15-52", "hanzi": "特点", "pinyin": "tèdiǎn", "meaning": "feature; characteristic", "example_cn": "字和字的组合也很有特点。", "example_en": "The way characters combine is also very distinctive.", "lesson": 15.5}, {"id": "15-53", "hanzi": "倒过来", "pinyin": "dào guòlái", "meaning": "to reverse; to turn around", "example_cn": "“球拍”倒过来，就是“拍球”。", "example_en": "Reverse \"qiupai\" and you get \"paiqiu\".", "lesson": 15.5}, {"id": "15-54", "hanzi": "新鲜", "pinyin": "xīnxiān", "meaning": "new; fresh", "example_cn": "哦，这倒很新鲜。", "example_en": "Oh, that's quite new to me.", "lesson": 15.5}, {"id": "15-55", "hanzi": "例子", "pinyin": "lìzi", "meaning": "example", "example_cn": "我们现在就来看个例子。", "example_en": "Let's look at an example now.", "lesson": 15.5}, {"id": "15-56", "hanzi": "球拍", "pinyin": "qiúpāi", "meaning": "racket; bat", "example_cn": "我手里拿着个球拍。", "example_en": "I am holding a racket.", "lesson": 15.5}, {"id": "15-57", "hanzi": "草原", "pinyin": "cǎoyuán", "meaning": "grassland; prairie", "example_cn": "草原上有很多奶牛。", "example_en": "There are many dairy cows on the grassland.", "lesson": 15.5}, {"id": "15-58", "hanzi": "复杂", "pinyin": "fùzá", "meaning": "complicated", "example_cn": "这道题有点儿复杂。", "example_en": "This question is a bit complicated.", "lesson": 15.5}, {"id": "15-59", "hanzi": "便宜", "pinyin": "piányi", "meaning": "cheap", "example_cn": "这种蛋糕没有那种便宜。", "example_en": "This kind of cake is not as cheap as that kind.", "lesson": 15.5}], "16.1": [{"id": "16-0", "hanzi": "学习", "pinyin": "xuéxí", "meaning": "to study; to learn", "example_cn": "学习要认真。", "example_en": "You should study seriously.", "lesson": 16.1}, {"id": "16-1", "hanzi": "钓鱼", "pinyin": "diàoyú", "meaning": "to fish", "example_cn": "小猫和妈妈去河边钓鱼。", "example_en": "The kitten and its mother go fishing by the river.", "lesson": 16.1}, {"id": "16-2", "hanzi": "钓鱼竿", "pinyin": "diàoyúgān", "meaning": "fishing rod", "example_cn": "猫妈妈拿着钓鱼竿。", "example_en": "Mother Cat is holding a fishing rod.", "lesson": 16.1}, {"id": "16-3", "hanzi": "一会儿", "pinyin": "yíhuìr", "meaning": "a moment; a little while", "example_cn": "请等我一会儿。", "example_en": "Please wait for me a moment.", "lesson": 16.1}, {"id": "16-4", "hanzi": "麻雀", "pinyin": "máquè", "meaning": "sparrow", "example_cn": "一只麻雀从树上飞了下来。", "example_en": "A sparrow flew down from the tree.", "lesson": 16.1}, {"id": "16-5", "hanzi": "蚯蚓", "pinyin": "qiūyǐn", "meaning": "earthworm", "example_cn": "泥土里钻出了一条蚯蚓。", "example_en": "An earthworm came out of the soil.", "lesson": 16.1}, {"id": "16-6", "hanzi": "螃蟹", "pinyin": "pángxiè", "meaning": "crab", "example_cn": "沙滩上爬过来一只螃蟹。", "example_en": "A crab crawled over on the beach.", "lesson": 16.1}, {"id": "16-7", "hanzi": "结果", "pinyin": "jiéguǒ", "meaning": "as a result; result", "example_cn": "小猫钓鱼不专心，结果一条鱼也没钓到。", "example_en": "The kitten didn't focus on fishing, so it didn't catch a single fish.", "lesson": 16.1}], "16.2": [{"id": "16-8", "hanzi": "欺负", "pinyin": "qīfu", "meaning": "to bully", "example_cn": "欺负同学是不对的。", "example_en": "Bullying classmates is wrong.", "lesson": 16.2}, {"id": "16-9", "hanzi": "照顾", "pinyin": "zhàogù", "meaning": "to take care of", "example_cn": "照顾宠物是不容易的。", "example_en": "Taking care of pets is not easy.", "lesson": 16.2}, {"id": "16-10", "hanzi": "宠物", "pinyin": "chǒngwù", "meaning": "pet", "example_cn": "我家的宠物是一只小狗。", "example_en": "Our family's pet is a puppy.", "lesson": 16.2}, {"id": "16-11", "hanzi": "容易", "pinyin": "róngyì", "meaning": "easy", "example_cn": "这道题很容易。", "example_en": "This question is very easy.", "lesson": 16.2}, {"id": "16-12", "hanzi": "姐妹俩", "pinyin": "jiěmèi liǎ", "meaning": "the two sisters", "example_cn": "姐妹俩一会儿唱歌，一会儿跳舞。", "example_en": "The two sisters sing for a while, then dance for a while.", "lesson": 16.2}, {"id": "16-13", "hanzi": "跳舞", "pinyin": "tiàowǔ", "meaning": "to dance", "example_cn": "妹妹最喜欢跳舞。", "example_en": "My little sister loves dancing the most.", "lesson": 16.2}, {"id": "16-14", "hanzi": "吹泡泡", "pinyin": "chuī pàopao", "meaning": "to blow bubbles", "example_cn": "他们俩在公园里吹泡泡。", "example_en": "The two of them are blowing bubbles in the park.", "lesson": 16.2}, {"id": "16-15", "hanzi": "溜滑轮", "pinyin": "liū huálún", "meaning": "to roller-skate", "example_cn": "哥哥喜欢在公园溜滑轮。", "example_en": "My older brother likes roller-skating in the park.", "lesson": 16.2}, {"id": "16-16", "hanzi": "专心", "pinyin": "zhuānxīn", "meaning": "focused; attentive", "example_cn": "上课要专心听老师讲课。", "example_en": "In class, listen attentively to the teacher.", "lesson": 16.2}, {"id": "16-17", "hanzi": "数学", "pinyin": "shùxué", "meaning": "mathematics", "example_cn": "大明上数学课不认真。", "example_en": "Daming isn't serious in maths class.", "lesson": 16.2}, {"id": "16-18", "hanzi": "道", "pinyin": "dào", "meaning": "measure word for questions", "example_cn": "这道题我不会做。", "example_en": "I can't do this question.", "lesson": 16.2}], "16.3": [{"id": "16-19", "hanzi": "却", "pinyin": "què", "meaning": "but; yet", "example_cn": "小华爱看书，却不爱写字。", "example_en": "Xiaohua loves reading but doesn't like writing.", "lesson": 16.3}, {"id": "16-20", "hanzi": "认识", "pinyin": "rènshi", "meaning": "to know; to recognise", "example_cn": "小华认为只要认识字就行了。", "example_en": "Xiaohua thought it was enough just to recognise characters.", "lesson": 16.3}, {"id": "16-21", "hanzi": "需要", "pinyin": "xūyào", "meaning": "to need", "example_cn": "我们需要多练习写字。", "example_en": "We need to practise writing more.", "lesson": 16.3}, {"id": "16-22", "hanzi": "听写", "pinyin": "tīngxiě", "meaning": "dictation", "example_cn": "今天华文课有听写。", "example_en": "There is a dictation in Chinese class today.", "lesson": 16.3}, {"id": "16-23", "hanzi": "吴老师", "pinyin": "Wú lǎoshī", "meaning": "Teacher Wu", "example_cn": "吴老师给同学们听写。", "example_en": "Teacher Wu gives the students a dictation.", "lesson": 16.3}, {"id": "16-24", "hanzi": "月亮", "pinyin": "yuèliang", "meaning": "moon", "example_cn": "今晚的月亮又大又圆。", "example_en": "The moon is big and round tonight.", "lesson": 16.3}, {"id": "16-25", "hanzi": "只好", "pinyin": "zhǐhǎo", "meaning": "to have no choice but to", "example_cn": "下雨了，我们只好在家里玩。", "example_en": "It's raining, so we have no choice but to play at home.", "lesson": 16.3}, {"id": "16-26", "hanzi": "圆圈", "pinyin": "yuánquān", "meaning": "circle", "example_cn": "他在纸上画了一个圆圈。", "example_en": "He drew a circle on the paper.", "lesson": 16.3}, {"id": "16-27", "hanzi": "代替", "pinyin": "dàitì", "meaning": "to replace; to substitute", "example_cn": "他用圆圈来代替不会写的字。", "example_en": "He used circles to replace the characters he couldn't write.", "lesson": 16.3}, {"id": "16-28", "hanzi": "传", "pinyin": "chuán", "meaning": "to pass", "example_cn": "请同学们把本子传上来。", "example_en": "Students, please pass your exercise books forward.", "lesson": 16.3}, {"id": "16-29", "hanzi": "本子", "pinyin": "běnzi", "meaning": "exercise book", "example_cn": "老师发回本子。", "example_en": "The teacher handed back the exercise books.", "lesson": 16.3}, {"id": "16-30", "hanzi": "念", "pinyin": "niàn", "meaning": "to read aloud", "example_cn": "小华大声地念他写的句子。", "example_en": "Xiaohua read his sentence aloud.", "lesson": 16.3}, {"id": "16-31", "hanzi": "句子", "pinyin": "jùzi", "meaning": "sentence", "example_cn": "请你用这个词语造句子。", "example_en": "Please make a sentence with this word.", "lesson": 16.3}, {"id": "16-32", "hanzi": "看不懂", "pinyin": "kàn bu dǒng", "meaning": "cannot understand (when reading)", "example_cn": "你写的字，别人都看不懂。", "example_en": "Nobody else can read what you wrote.", "lesson": 16.3}, {"id": "16-33", "hanzi": "难为情", "pinyin": "nánwéiqíng", "meaning": "embarrassed", "example_cn": "被大家笑了，小华很难为情。", "example_en": "Xiaohua was embarrassed when everyone laughed.", "lesson": 16.3}, {"id": "16-34", "hanzi": "低下", "pinyin": "dīxià", "meaning": "to lower", "example_cn": "他低下了头。", "example_en": "He lowered his head.", "lesson": 16.3}, {"id": "16-35", "hanzi": "敢", "pinyin": "gǎn", "meaning": "to dare", "example_cn": "弟弟不敢一个人睡觉。", "example_en": "My little brother doesn't dare to sleep alone.", "lesson": 16.3}, {"id": "16-36", "hanzi": "抬起", "pinyin": "táiqǐ", "meaning": "to raise; to lift up", "example_cn": "他不好意思抬起头来。", "example_en": "He was too embarrassed to raise his head.", "lesson": 16.3}, {"id": "16-37", "hanzi": "明白", "pinyin": "míngbai", "meaning": "to understand", "example_cn": "小华明白了写字很重要。", "example_en": "Xiaohua understood that writing is very important.", "lesson": 16.3}, {"id": "16-38", "hanzi": "重要", "pinyin": "zhòngyào", "meaning": "important", "example_cn": "认真写字很重要。", "example_en": "Writing carefully is very important.", "lesson": 16.3}], "16.4": [{"id": "16-39", "hanzi": "故事书", "pinyin": "gùshishū", "meaning": "storybook", "example_cn": "小华爱看故事书。", "example_en": "Xiaohua loves reading storybooks.", "lesson": 16.4}], "16.5": [{"id": "16-40", "hanzi": "书法家", "pinyin": "shūfǎjiā", "meaning": "calligrapher", "example_cn": "王献之是一位有名的书法家。", "example_en": "Wang Xianzhi was a famous calligrapher.", "lesson": 16.5}, {"id": "16-41", "hanzi": "赞美", "pinyin": "zànměi", "meaning": "praise", "example_cn": "他常常得到别人的赞美。", "example_en": "He often received praise from others.", "lesson": 16.5}, {"id": "16-42", "hanzi": "了不起", "pinyin": "liǎobuqǐ", "meaning": "amazing; remarkable", "example_cn": "他觉得自己很了不起。", "example_en": "He thought he was amazing.", "lesson": 16.5}, {"id": "16-43", "hanzi": "得意", "pinyin": "déyì", "meaning": "proud; pleased with oneself", "example_cn": "他考了一百分，非常得意。", "example_en": "He got 100 marks and was very pleased with himself.", "lesson": 16.5}, {"id": "16-44", "hanzi": "练字", "pinyin": "liàn zì", "meaning": "to practise handwriting", "example_cn": "我每天都练字。", "example_en": "I practise my handwriting every day.", "lesson": 16.5}, {"id": "16-45", "hanzi": "母亲", "pinyin": "mǔqin", "meaning": "mother", "example_cn": "王献之把字拿给母亲看。", "example_en": "Wang Xianzhi showed his writing to his mother.", "lesson": 16.5}, {"id": "16-46", "hanzi": "功夫", "pinyin": "gōngfu", "meaning": "skill; effort", "example_cn": "我写字的功夫还不到家。", "example_en": "My writing skills are not good enough yet.", "lesson": 16.5}, {"id": "16-47", "hanzi": "教导", "pinyin": "jiàodǎo", "meaning": "to teach; to guide", "example_cn": "请父亲多教导！", "example_en": "Father, please teach me more!", "lesson": 16.5}, {"id": "16-48", "hanzi": "院子", "pinyin": "yuànzi", "meaning": "courtyard; yard", "example_cn": "院子里有十八口大水缸。", "example_en": "There are eighteen big water vats in the courtyard.", "lesson": 16.5}, {"id": "16-49", "hanzi": "刻苦", "pinyin": "kèkǔ", "meaning": "hardworking; painstaking", "example_cn": "经过刻苦练习，他的字越写越好。", "example_en": "After hard practice, his writing got better and better.", "lesson": 16.5}], "17.1": [{"id": "17-0", "hanzi": "好孩子", "pinyin": "hǎo háizi", "meaning": "good child", "example_cn": "诚实的孩子是好孩子。", "example_en": "An honest child is a good child.", "lesson": 17.1}, {"id": "17-1", "hanzi": "斧头", "pinyin": "fǔtóu", "meaning": "axe", "example_cn": "年轻人用斧头砍柴。", "example_en": "The young man chops firewood with an axe.", "lesson": 17.1}, {"id": "17-2", "hanzi": "砍", "pinyin": "kǎn", "meaning": "to chop", "example_cn": "爸爸在院子里砍树。", "example_en": "Dad is chopping a tree in the yard.", "lesson": 17.1}, {"id": "17-3", "hanzi": "年轻人", "pinyin": "niánqīngrén", "meaning": "young person", "example_cn": "年轻人在河边砍柴。", "example_en": "The young man is chopping firewood by the river.", "lesson": 17.1}, {"id": "17-4", "hanzi": "柴", "pinyin": "chái", "meaning": "firewood", "example_cn": "他每天上山砍柴。", "example_en": "He goes up the mountain to chop firewood every day.", "lesson": 17.1}, {"id": "17-5", "hanzi": "神仙", "pinyin": "shénxiān", "meaning": "immortal; fairy", "example_cn": "河里出现了一位神仙。", "example_en": "An immortal appeared in the river.", "lesson": 17.1}, {"id": "17-6", "hanzi": "捞出", "pinyin": "lāochū", "meaning": "to fish out (of water)", "example_cn": "神仙从河里捞出一把金斧头。", "example_en": "The immortal fished a golden axe out of the river.", "lesson": 17.1}, {"id": "17-7", "hanzi": "银", "pinyin": "yín", "meaning": "silver", "example_cn": "神仙又捞出一把银斧头。", "example_en": "The immortal then fished out a silver axe.", "lesson": 17.1}], "17.2": [{"id": "17-8", "hanzi": "不小心", "pinyin": "bù xiǎoxīn", "meaning": "carelessly; accidentally", "example_cn": "他不小心把斧头掉进河里。", "example_en": "He accidentally dropped the axe into the river.", "lesson": 17.2}, {"id": "17-9", "hanzi": "掉进", "pinyin": "diàojìn", "meaning": "to fall into", "example_cn": "我的球掉进水里了。", "example_en": "My ball fell into the water.", "lesson": 17.2}, {"id": "17-10", "hanzi": "牛油", "pinyin": "niúyóu", "meaning": "butter", "example_cn": "妹妹不小心把牛油弄到裙子上。", "example_en": "My sister accidentally got butter on her skirt.", "lesson": 17.2}, {"id": "17-11", "hanzi": "裙子", "pinyin": "qúnzi", "meaning": "skirt; dress", "example_cn": "姐姐穿着一条红裙子。", "example_en": "My older sister is wearing a red dress.", "lesson": 17.2}, {"id": "17-12", "hanzi": "小心", "pinyin": "xiǎoxīn", "meaning": "carefully; careful", "example_cn": "过马路时要小心。", "example_en": "Be careful when crossing the road.", "lesson": 17.2}, {"id": "17-13", "hanzi": "咖啡", "pinyin": "kāfēi", "meaning": "coffee", "example_cn": "姐姐小心地把咖啡倒进杯子里。", "example_en": "My older sister carefully poured the coffee into the cup.", "lesson": 17.2}, {"id": "17-14", "hanzi": "杯子", "pinyin": "bēizi", "meaning": "cup", "example_cn": "桌上有一个杯子。", "example_en": "There is a cup on the table.", "lesson": 17.2}, {"id": "17-15", "hanzi": "藏", "pinyin": "cáng", "meaning": "to hide", "example_cn": "哥哥把礼物藏在桌子底下。", "example_en": "My older brother hid the present under the table.", "lesson": 17.2}, {"id": "17-16", "hanzi": "底下", "pinyin": "dǐxia", "meaning": "under; beneath", "example_cn": "小猫躲在床底下。", "example_en": "The kitten is hiding under the bed.", "lesson": 17.2}, {"id": "17-17", "hanzi": "不但", "pinyin": "búdàn", "meaning": "not only", "example_cn": "他不但会唱歌，还会跳舞。", "example_en": "He can not only sing but also dance.", "lesson": 17.2}, {"id": "17-18", "hanzi": "失去", "pinyin": "shīqù", "meaning": "to lose", "example_cn": "他没有失去铁斧头。", "example_en": "He did not lose his iron axe.", "lesson": 17.2}, {"id": "17-19", "hanzi": "铁", "pinyin": "tiě", "meaning": "iron", "example_cn": "这把斧头是铁做的。", "example_en": "This axe is made of iron.", "lesson": 17.2}, {"id": "17-20", "hanzi": "金", "pinyin": "jīn", "meaning": "gold", "example_cn": "他还得到了金斧头。", "example_en": "He also got a golden axe.", "lesson": 17.2}, {"id": "17-21", "hanzi": "游泳", "pinyin": "yóuyǒng", "meaning": "to swim", "example_cn": "我每个星期六去游泳。", "example_en": "I go swimming every Saturday.", "lesson": 17.2}, {"id": "17-22", "hanzi": "比赛", "pinyin": "bǐsài", "meaning": "competition; match", "example_cn": "他参加了跑步比赛。", "example_en": "He took part in the running race.", "lesson": 17.2}, {"id": "17-23", "hanzi": "跑步", "pinyin": "pǎobù", "meaning": "to run; running", "example_cn": "我每天早上去公园跑步。", "example_en": "I go running in the park every morning.", "lesson": 17.2}], "17.3": [{"id": "17-24", "hanzi": "试卷", "pinyin": "shìjuàn", "meaning": "test paper", "example_cn": "老师发回了数学试卷。", "example_en": "The teacher handed back the maths test papers.", "lesson": 17.3}, {"id": "17-25", "hanzi": "家长", "pinyin": "jiāzhǎng", "meaning": "parent", "example_cn": "试卷要带回家给家长看。", "example_en": "The test paper must be taken home for a parent to see.", "lesson": 17.3}, {"id": "17-26", "hanzi": "签名", "pinyin": "qiānmíng", "meaning": "to sign; signature", "example_cn": "请妈妈在试卷上签名。", "example_en": "Ask Mum to sign the test paper.", "lesson": 17.3}, {"id": "17-27", "hanzi": "考试", "pinyin": "kǎoshì", "meaning": "exam; test", "example_cn": "这次考试我得了一百分。", "example_en": "I got 100 marks in this test.", "lesson": 17.3}, {"id": "17-28", "hanzi": "一百", "pinyin": "yìbǎi", "meaning": "one hundred", "example_cn": "这本书有一百页。", "example_en": "This book has one hundred pages.", "lesson": 17.3}, {"id": "17-29", "hanzi": "兴高采烈", "pinyin": "xìng gāo cǎi liè", "meaning": "in high spirits", "example_cn": "我兴高采烈地跑回家。", "example_en": "I ran home in high spirits.", "lesson": 17.3}, {"id": "17-30", "hanzi": "消息", "pinyin": "xiāoxi", "meaning": "news", "example_cn": "我告诉妈妈这个好消息。", "example_en": "I told Mum the good news.", "lesson": 17.3}, {"id": "17-31", "hanzi": "等", "pinyin": "děng", "meaning": "to wait", "example_cn": "等她回来后再签。", "example_en": "She'll sign it after she comes back.", "lesson": 17.3}, {"id": "17-32", "hanzi": "上班", "pinyin": "shàngbān", "meaning": "to go to work", "example_cn": "妈妈已经上班去了。", "example_en": "Mum has already gone to work.", "lesson": 17.3}, {"id": "17-33", "hanzi": "便条", "pinyin": "biàntiáo", "meaning": "short note", "example_cn": "桌上有一张便条。", "example_en": "There is a note on the table.", "lesson": 17.3}, {"id": "17-34", "hanzi": "题", "pinyin": "tí", "meaning": "question (in a test)", "example_cn": "第一题的答案是一万。", "example_en": "The answer to the first question is ten thousand.", "lesson": 17.3}, {"id": "17-35", "hanzi": "答案", "pinyin": "dá'àn", "meaning": "answer", "example_cn": "这道题的答案是什么？", "example_en": "What is the answer to this question?", "lesson": 17.3}, {"id": "17-36", "hanzi": "一万", "pinyin": "yíwàn", "meaning": "ten thousand", "example_cn": "这个城市有一万棵树。", "example_en": "This city has ten thousand trees.", "lesson": 17.3}, {"id": "17-37", "hanzi": "一千", "pinyin": "yìqiān", "meaning": "one thousand", "example_cn": "答案不是一千。", "example_en": "The answer is not one thousand.", "lesson": 17.3}, {"id": "17-38", "hanzi": "减掉", "pinyin": "jiǎndiào", "meaning": "to deduct; to take away", "example_cn": "你答错了，应该减掉两分。", "example_en": "You answered wrongly, so two marks should be deducted.", "lesson": 17.3}, {"id": "17-39", "hanzi": "重新", "pinyin": "chóngxīn", "meaning": "again; anew", "example_cn": "请老师重新算一算分数。", "example_en": "Ask the teacher to work out the marks again.", "lesson": 17.3}, {"id": "17-40", "hanzi": "算", "pinyin": "suàn", "meaning": "to calculate", "example_cn": "请你算出这道题的答案。", "example_en": "Please work out the answer to this question.", "lesson": 17.3}, {"id": "17-41", "hanzi": "检查", "pinyin": "jiǎnchá", "meaning": "to check", "example_cn": "我立刻检查试卷。", "example_en": "I checked the test paper right away.", "lesson": 17.3}, {"id": "17-42", "hanzi": "立刻", "pinyin": "lìkè", "meaning": "immediately", "example_cn": "听到铃声，我们立刻排队。", "example_en": "When we heard the bell, we lined up immediately.", "lesson": 17.3}, {"id": "17-43", "hanzi": "满分", "pinyin": "mǎnfēn", "meaning": "full marks", "example_cn": "如果告诉老师，我就不是满分了。", "example_en": "If I tell the teacher, I won't have full marks.", "lesson": 17.3}, {"id": "17-44", "hanzi": "不安", "pinyin": "bù'ān", "meaning": "uneasy; worried", "example_cn": "如果不告诉老师，我心里感到不安。", "example_en": "If I don't tell the teacher, I will feel uneasy.", "lesson": 17.3}], "17.4": [{"id": "17-45", "hanzi": "路不拾遗", "pinyin": "lù bù shí yí", "meaning": "no one pockets things lost on the road (honest society)", "example_cn": "这个地方路不拾遗，人人都很诚实。", "example_en": "Here no one keeps what is dropped on the road; everyone is honest.", "lesson": 17.4}, {"id": "17-46", "hanzi": "包袱", "pinyin": "bāofu", "meaning": "cloth-wrapped bundle", "example_cn": "商人发现包袱丢了。", "example_en": "The merchant found that his bundle was lost.", "lesson": 17.4}, {"id": "17-47", "hanzi": "诚实", "pinyin": "chéngshí", "meaning": "honest", "example_cn": "我们要做诚实的人。", "example_en": "We should be honest people.", "lesson": 17.4}], "17.5": [{"id": "17-48", "hanzi": "拾到", "pinyin": "shídào", "meaning": "to pick up; to find", "example_cn": "我拾到了一支漂亮的铅笔。", "example_en": "I found a pretty pencil.", "lesson": 17.5}, {"id": "17-49", "hanzi": "铅笔", "pinyin": "qiānbǐ", "meaning": "pencil", "example_cn": "我用铅笔写字。", "example_en": "I write with a pencil.", "lesson": 17.5}, {"id": "17-50", "hanzi": "橡皮", "pinyin": "xiàngpí", "meaning": "eraser", "example_cn": "我向同学借了一块橡皮。", "example_en": "I borrowed an eraser from a classmate.", "lesson": 17.5}, {"id": "17-51", "hanzi": "口袋", "pinyin": "kǒudai", "meaning": "pocket", "example_cn": "我真想放进自己的口袋里。", "example_en": "I really wanted to put it in my own pocket.", "lesson": 17.5}, {"id": "17-52", "hanzi": "食堂", "pinyin": "shítáng", "meaning": "canteen", "example_cn": "我们在食堂吃午饭。", "example_en": "We eat lunch in the canteen.", "lesson": 17.5}, {"id": "17-53", "hanzi": "阿姨", "pinyin": "āyí", "meaning": "auntie", "example_cn": "快快把它还给阿姨。", "example_en": "Quickly give it back to the auntie.", "lesson": 17.5}, {"id": "17-54", "hanzi": "闯祸", "pinyin": "chuǎnghuò", "meaning": "to get into trouble", "example_cn": "弟弟又闯祸了。", "example_en": "My little brother got into trouble again.", "lesson": 17.5}, {"id": "17-55", "hanzi": "墙角", "pinyin": "qiángjiǎo", "meaning": "corner (of a wall)", "example_cn": "我吓得躲进墙角里。", "example_en": "I was so scared I hid in the corner.", "lesson": 17.5}, {"id": "17-56", "hanzi": "赔偿", "pinyin": "péicháng", "meaning": "to compensate; to pay for", "example_cn": "我拿着钱去赔偿老奶奶的玻璃。", "example_en": "I took the money to pay for the old lady's window.", "lesson": 17.5}, {"id": "17-57", "hanzi": "宁可", "pinyin": "nìngkě", "meaning": "would rather", "example_cn": "我宁可只要真实的九十七分。", "example_en": "I would rather have an honest 97 marks.", "lesson": 17.5}]};
